// Runtime half of #parser{} for generated-reader targets. The compiler owns
// grammar parsing and code generation; the resulting reader needs only tokens
// and the PNode tree it constructs.
include "std/tok.lang"
include "std/pnode.lang"

example/tiny/tiny.lang:
// The smallest useful reader: `answer 42` becomes a complete native program.

include "std/tok.lang"
include "std/ast.lang"

reader tiny(text *u8) *u8 {
    var tokens *Tokenizer = tok_new(text);
    if tok_kind(tokens) != TOK_IDENT || !streq(tok_text(tokens), "answer") {
        eprintln("tiny: expected `answer NUMBER`");
        return nil;
    }
    tok_next(tokens);
    if tok_kind(tokens) != TOK_NUMBER {
        eprintln("tiny: expected a number");
        return nil;
    }

    return ast_main_i64(ast_number(tok_text(tokens)));
}

example/calc/calc.lang:
// A small reader with a real grammar: `answer (2 + 3) * 4`.

include "std/tok.lang"
include "std/ast.lang"

func calc_primary(tokens *Tokenizer) *u8 {
    if tok_kind(tokens) == TOK_NUMBER {
        var value *u8 = ast_number(tok_text(tokens));
        tok_next(tokens);
        return value;
    }

    if tok_match(tokens, TOK_LPAREN) {
        var expr *u8 = calc_expr(tokens);
        if expr == nil { return nil; }
        if !tok_expect(tokens, TOK_RPAREN) {
            eprintln("calc: expected `)`");
            return nil;
        }
        return expr;
    }

    eprintln("calc: expected a number or `(`");
    return nil;
}

func calc_term(tokens *Tokenizer) *u8 {
    var left *u8 = calc_primary(tokens);
    if left == nil { return nil; }

    while tok_kind(tokens) == TOK_STAR || tok_kind(tokens) == TOK_SLASH ||
          tok_kind(tokens) == TOK_PERCENT {
        var op i64 = tok_kind(tokens);
        tok_next(tokens);
        var right *u8 = calc_primary(tokens);
        if right == nil { return nil; }

        if op == TOK_STAR { left = ast_mul(left, right); }
        else if op == TOK_SLASH { left = ast_div(left, right); }
        else { left = ast_mod(left, right); }
    }
    return left;
}

func calc_expr(tokens *Tokenizer) *u8 {
    var left *u8 = calc_term(tokens);
    if left == nil { return nil; }

    while tok_kind(tokens) == TOK_PLUS || tok_kind(tokens) == TOK_MINUS {
        var op i64 = tok_kind(tokens);
        tok_next(tokens);
        var right *u8 = calc_term(tokens);
        if right == nil { return nil; }

        if op == TOK_PLUS { left = ast_add(left, right); }
        else { left = ast_sub(left, right); }
    }
    return left;
}

reader calc(text *u8) *u8 {
    var tokens *Tokenizer = tok_new(text);
    if tok_kind(tokens) != TOK_IDENT || !streq(tok_text(tokens), "answer") {
        eprintln("calc: expected `answer EXPRESSION`");
        return nil;
    }
    tok_next(tokens);

    var value *u8 = calc_expr(tokens);
    if value == nil { return nil; }
    if !tok_eof(tokens) {
        eprintln("calc: unexpected token after expression");
        return nil;
    }

    var body *u8 = ast_block1(ast_return(value));
    return ast_program1(ast_func("main", ast_vec(), ast_type_i64(), body));
}

example/c/c.lang:
// ============================================================
// c - A C-subset reader (capture real C, compile to native)
// ============================================================
//
// Proves the reader-authorship thesis on a REAL language: a subset of C
// maps almost 1:1 onto lang's C-like AST. Built with #parser{} (the crown
// jewel, Level 3) for parsing, plus a converter that lowers the parse tree to
// lang AST via the std/ast.lang builder API (Level 1) - NO hand-written S-expr
// strings. The converter does operator precedence-climbing.
//
//   #c{ int factorial(int n) { if (n < 2) return 1; return n * factorial(n - 1); } }
//
// Then factorial() is a normal native function, callable from lang.
//
// SUBSET (deliberately bounded - no typedef/preprocessor/declarators):
//   types:      int, char, void (int/char->i64/u8), pointers (T*), struct Name
//   decls:      structs (struct N { ... };), funcs, local decls (init optional)
//   statements: return, if/else, while, for, assignment, blocks, expr statements
//   operators:  + - * / %  < > <= >= == != && ||, unary - ! ~ * &, ternary ?:,
//               calls f(a,b), member access p.f and (*p).f  (-> lexed as .)
//   strings:    "..." literals (char*); funcs may return non-struct types only
//
// rdgen handles ordered alternatives transactionally. This grammar still uses
// keyword-led named statement rules because that shape is easy to inspect and
// produces smaller parse trees. Operator precedence is flat in the grammar and
// resolved here.

// require (not include) so the -r composition path can filter them: the kernel
// already carries std/core and std/tok, and this lets `kernel -r c c.ast`
// build a standalone C compiler without duplicating their declarations.
require "std/core"
require "std/tok"
include "std/parser_reader.lang"
include "std/ast.lang"

// All rules are c_-prefixed: bare names like program/type/block/primary would
// generate parse_program/parse_type/... which COLLIDE with the compiler's own
// parser functions (pulled in transitively via lang_reader).
#parser{
    c_program    = c_topdecl+
    c_topdecl    = c_structdef | c_enumdef | c_topvar
    c_topvar     = c_rettype symbol c_topvartail
    c_topvartail = c_functail | c_globaltail
    c_functail   = '(' c_params ')' c_block
    c_globaltail = c_arrdim c_initopt ';'
    c_structdef  = 'struct' symbol '{' c_fields '}' ';'
    c_fields     = c_field*
    c_field      = c_ptype symbol ';'
    c_enumdef    = 'enum' c_enumtag '{' c_enumitems '}' ';'
    c_enumtag    = c_tagname*
    c_tagname    = symbol
    c_enumitems  = c_enumitem*
    c_enumitem   = c_enummember | ','
    c_enummember = symbol c_enumvalopt
    c_enumvalopt = c_enumval*
    c_enumval    = '=' number
    c_rettype    = c_basetype c_stars
    c_ptype      = c_anytype c_stars
    c_anytype    = c_basetype | c_structtype | c_enumtype
    c_basetype   = 'int' | 'char' | 'void'
    c_structtype = 'struct' symbol
    c_enumtype   = 'enum' symbol
    c_stars      = c_star*
    c_star       = '*'
    c_params     = c_paramitem*
    c_paramitem  = c_param | ','
    c_param      = c_ptype symbol
    c_block     = '{' c_stmt* '}'
    c_stmt      = c_retstmt | c_ifstmt | c_whilestmt | c_forstmt | c_switchstmt | c_breakstmt | c_continuestmt | c_decl | c_block | c_exprstmt
    c_switchstmt = 'switch' '(' c_expr ')' '{' c_switchitems '}'
    c_switchitems = c_switchitem*
    c_switchitem = c_caseval | c_defaultlabel | c_stmt
    c_caseval    = 'case' c_expr ':'
    c_defaultlabel = 'default' ':'
    c_breakstmt = 'break' ';'
    c_continuestmt = 'continue' ';'
    c_retstmt   = 'return' c_expr ';'
    c_ifstmt    = 'if' '(' c_expr ')' c_stmt c_elses
    c_elses     = c_elsepart*
    c_elsepart  = 'else' c_stmt
    c_whilestmt = 'while' '(' c_expr ')' c_stmt
    c_forstmt   = 'for' '(' c_forinit c_expr ';' c_expr ')' c_stmt
    c_forinit   = c_decl | c_exprstmt
    c_decl      = c_ptype symbol c_arrdim c_initopt ';'
    c_arrdim    = c_dim*
    c_dim       = '[' number ']'
    c_initopt   = c_initval*
    c_initval   = '=' c_expr
    c_exprstmt  = c_expr ';'
    c_expr      = c_binexpr c_terntail*
    c_terntail  = '?' c_expr ':' c_expr
    c_binexpr   = c_unary c_oprest*
    c_oprest    = operator c_unary?
    c_unary     = c_neg | c_postfix
    c_neg       = operator c_postfix
    c_postfix   = c_primary c_postfixop*
    c_postfixop = c_callargs | c_member | c_index
    c_callargs  = '(' c_args ')'
    c_member    = '.' symbol | '->' symbol
    c_index     = '[' c_expr ']'
    c_args      = c_argitem*
    c_argitem   = c_expr | ','
    c_primary   = number | string | symbol | c_parenexpr
    c_parenexpr = '(' c_expr ')'
}

// PNode kinds: 1=number, 2=symbol, 3=string, 4=list/sequence, 5=operator, 0=literal marker

// ============================================================
// Operator precedence (higher binds tighter)
// ============================================================

// C precedence ladder (low binds loosest). The tokenizer already lexes the
// 2-char operators (==, !=, <=, >=, &&, ||) and carries their text, so they just
// need a precedence here. '=' is prec 0: it's peeled off as an assignment
// statement, never climbed as a binop.
func prec(op *u8) i64 {
    if streq(op, "||") { return 1; }
    if streq(op, "&&") { return 2; }
    if streq(op, "|") { return 3; }                                  // bitwise or
    if streq(op, "^") { return 4; }                                  // bitwise xor
    if streq(op, "&") { return 5; }                                  // bitwise and
    if streq(op, "==") || streq(op, "!=") { return 6; }
    if streq(op, "<") || streq(op, ">") || streq(op, "<=") || streq(op, ">=") { return 7; }
    if streq(op, "<<") || streq(op, ">>") { return 8; }              // shifts
    if streq(op, "+") || streq(op, "-") { return 9; }
    if streq(op, "*") || streq(op, "/") || streq(op, "%") { return 10; }
    return 0;
}

// ============================================================
// Expression emission (precedence climbing over a flat operand/op list)
// ============================================================

// Split a c_binexpr (= c_unary c_oprest*) into parallel operand/op vecs
// (operands[i] is followed by ops[i]). Shared by expression emission and
// assignment detection. (The ternary tail, if any, is handled by the caller.)
func flatten_expr(e *PNode, operands *u8, ops *u8) void {
    vec_push(operands, vec_get(e.children, 0));
    var star *PNode = vec_get(e.children, 1);
    var m i64 = vec_len(star.children);
    var i i64 = 0;
    while i < m {
        var orn *PNode = vec_get(star.children, i);  // oprest = [op_atom, postfix]
        vec_push(ops, vec_get(orn.children, 0));
        // A trailing postfix ++/-- has no right operand (the grammar makes it
        // optional), so the oprest is just [op]; leave operands one shorter.
        if vec_len(orn.children) > 1 {
            vec_push(operands, vec_get(orn.children, 1));
        }
        i = i + 1;
    }
}

// A c_expr is `c_binexpr c_terntail*`: emit the binexpr value, then fold any
// ternary tail around it. (A flat binexpr is children[0]; the star is children[1].)
func emit_expr_str(e *PNode) *u8 {
    var binexpr *PNode = vec_get(e.children, 0);
    var terntail *PNode = vec_get(e.children, 1);
    var operands *u8 = vec_new(8);
    var ops *u8 = vec_new(8);
    flatten_expr(binexpr, operands, ops);
    var pos i64 = 0;
    var base *u8 = climb(operands, ops, &pos, 0);
    if vec_len(terntail.children) > 0 {
        return emit_ternary(base, vec_get(terntail.children, 0));
    }
    return base;
}

// Per-node-unique temp name (block/block_expr vars leak to the enclosing scope,
// so ternary temps and switch scrutinees each need their own; derive it from the
// node's address). Distinct prefixes + distinct node pointers => no collisions.
func c_gensym(prefix *u8, node *PNode) *u8 {
    var sb *StringBuilder = sb_new();
    sb_str(sb, prefix);
    var addr i64 = node;
    sb_int(sb, addr);
    return sb_finish(sb);
}

func ternary_tmp(node *PNode) *u8 {
    return c_gensym("__ct", node);
}

// `cond ? a : b` -> a value-returning block_expr (only the taken branch runs):
//   { var t = 0; if (cond) { t = a; } else { t = b; }  t }
// tt is a c_terntail = ['?', then_expr, ':', else_expr]. The temp is i64, which
// covers the bounded subset's int and pointer values.
func emit_ternary(cond *u8, tt *PNode) *u8 {
    var t *u8 = ternary_tmp(tt);
    var thenexpr *u8 = emit_expr_str(vec_get(tt.children, 1));
    var elseexpr *u8 = emit_expr_str(vec_get(tt.children, 3));
    var stmts *u8 = ast_vec();
    ast_push(stmts, ast_var(t, ast_type_i64(), ast_int(0)));
    ast_push(stmts, ast_if(cond,
                           ast_block1(ast_assign(ast_ident(t), thenexpr)),
                           ast_block1(ast_assign(ast_ident(t), elseexpr))));
    return ast_block_expr(stmts, ast_ident(t));
}

// Standard precedence climbing. operands[pos] aligns with ops[pos].
func climb(operands *u8, ops *u8, posptr *i64, minprec i64) *u8 {
    if *posptr >= vec_len(operands) { return ast_int(0); }   // defensive (dangling postfix op)
    var left *u8 = emit_operand_str(vec_get(operands, *posptr));
    var nops i64 = vec_len(ops);
    while *posptr < nops {
        var opnode *PNode = vec_get(ops, *posptr);
        // A postfix ++/-- in value position (not a statement) has no right operand
        // and is unsupported: skip it (side effect honored only at statement level).
        if streq(opnode.text, "++") || streq(opnode.text, "--") {
            *posptr = *posptr + 1;
        } else {
            var p i64 = prec(opnode.text);
            if p < minprec { return left; }
            *posptr = *posptr + 1;                               // consume operator
            var right *u8 = climb(operands, ops, posptr, p + 1); // left-associative
            left = ast_binop(opnode.text, left, right);
        }
    }
    return left;
}

// An operand is a c_unary = c_neg | c_postfix. The CHOICE returns the chosen
// node directly, so we tell them apart by their first child: c_neg leads with an
// operator atom (kind 5), c_postfix leads with a primary (kind 1/2/4).
func emit_operand_str(node *PNode) *u8 {
    var f *PNode = vec_get(node.children, 0);
    if f.kind == 5 {                          // c_neg = [op_atom, postfix]
        var operand *u8 = emit_postfix_str(vec_get(node.children, 1));
        if streq(f.text, "~") {               // ~x == x ^ -1 (kernel has no unary ~)
            return ast_binop("^", operand, ast_unop("-", ast_int(1)));
        }
        return ast_unop(f.text, operand);
    }
    return emit_postfix_str(node);            // c_postfix
}

// If `primary` is a parenthesized lone deref `(*X)`, return the c_postfix node X
// being dereferenced; else nil. Used to peel C's explicit deref before a member
// access (see emit_postfix_str).
func deref_paren_inner(primary *PNode) *PNode {
    if primary.kind != 4 { return nil; }              // parenexpr is a list node
    var c0 *PNode = vec_get(primary.children, 0);
    if c0.kind != 0 { return nil; }                   // ...leading with a '(' marker
    var inner *PNode = vec_get(primary.children, 1);  // the c_expr = [c_binexpr, terntail*]
    var terntail *PNode = vec_get(inner.children, 1);
    if vec_len(terntail.children) != 0 { return nil; } // a ternary is not a lone deref
    var binexpr *PNode = vec_get(inner.children, 0);  // c_binexpr = [c_unary, c_oprest*]
    var orest *PNode = vec_get(binexpr.children, 1);  // c_oprest*
    if vec_len(orest.children) != 0 { return nil; }   // must be a lone unary
    var u *PNode = vec_get(binexpr.children, 0);      // c_unary
    var u0 *PNode = vec_get(u.children, 0);
    if u0.kind == 5 && streq(u0.text, "*") {          // c_neg with '*'
        return vec_get(u.children, 1);                // the c_postfix being deref'd
    }
    return nil;
}

// postfix = primary postfixop*  ->  fold the chain left-to-right. Each op is a
// call (c_callargs = ['(', args, ')'], so children[1] is the args list, kind 4)
// or a member access (c_member = ['.', name], so children[1] is the name, kind 2).
func emit_postfix_str(pf *PNode) *u8 {
    var primary *PNode = vec_get(pf.children, 0);
    var ops *PNode = vec_get(pf.children, 1);     // star list of c_postfixop
    var nops i64 = vec_len(ops.children);

    // C's (*p).field is lang's auto-deref p.field. When a member access follows a
    // parenthesized lone deref, peel the '*' and emit (field p ...): the kernel
    // auto-derefs pointer.field, whereas (field (unop * p) ...) would load a
    // struct value and crash.
    var base *u8 = nil;
    var peeled *PNode = nil;
    if nops > 0 {
        var op0 *PNode = vec_get(ops.children, 0);
        var op0second *PNode = vec_get(op0.children, 1);
        if op0second.kind == 2 {                   // first op is a member
            peeled = deref_paren_inner(primary);
        }
    }
    if peeled != nil {
        base = emit_postfix_str(peeled);
    } else {
        base = emit_primary_str(primary);
    }

    var oi i64 = 0;
    while oi < nops {
        var op *PNode = vec_get(ops.children, oi);
        var second *PNode = vec_get(op.children, 1);
        if second.kind == 2 {                     // c_member = ['.', name] -> (field base name)
            base = ast_field(base, second.text);
        } else {
            // call and index both have a kind-4 second child; distinguish by the
            // leading marker's text ('(' vs '[' - markers carry their text).
            var marker *PNode = vec_get(op.children, 0);
            if streq(marker.text, "[") {          // c_index = ['[', expr, ']'] -> (index base idx)
                base = ast_index(base, emit_expr_str(second));
            } else {                              // c_callargs -> (call base args...)
                var args *u8 = ast_vec();
                var items *u8 = second.children;
                var n i64 = vec_len(items);
                var i i64 = 0;
                while i < n {
                    var it *PNode = vec_get(items, i);
                    if it.kind != 0 {            // skip ',' markers; args are expr nodes
                        ast_push(args, emit_expr_str(it));
                    }
                    i = i + 1;
                }
                base = ast_call(base, args);
            }
        }
        oi = oi + 1;
    }
    return base;
}

func emit_primary_str(p *PNode) *u8 {
    if p.kind == 1 {               // number
        return ast_number(p.text);
    }
    if p.kind == 2 {               // symbol -> ident
        return ast_ident(p.text);
    }
    if p.kind == 3 {               // TOK_STRING: "..." string OR '...' char literal
        if *(p.text) == 39 {       // leading ' -> C char literal, an integer value
            return ast_int(char_literal_value(p.text));
        }
        return ast_string_raw(p.text);  // "..." string; text keeps its quotes for the kernel
    }
    if p.kind == 4 {               // parenexpr = ['(', expr, ')']
        return emit_expr_str(vec_get(p.children, 1));
    }
    return ast_int(0);
}

// Value of a C char literal token (text includes the single quotes, e.g. 'a' or
// '\n'). Handles the common backslash escapes.
func char_literal_value(text *u8) i64 {
    var c i64 = *(text + 1);       // first char after the opening quote
    if c == 92 {                   // backslash escape
        var e i64 = *(text + 2);
        if e == 110 { return 10; }     // \n
        if e == 116 { return 9; }      // \t
        if e == 114 { return 13; }     // \r
        if e == 48 { return 0; }       // \0
        if e == 92 { return 92; }      // \\
        if e == 39 { return 39; }      // \'
        return e;                      // \<other> -> literal char
    }
    return c;
}

// ============================================================
// Statement emission
// ============================================================

func emit_stmt(s *PNode) *u8 {
    var first *PNode = vec_get(s.children, 0);

    if first.kind == 0 {           // block: leading '{' marker
        return emit_block(s);
    }

    if first.kind == 2 {
        if streq(first.text, "break") { return ast_break(nil); }
        if streq(first.text, "continue") { return ast_continue(nil); }
        if streq(first.text, "return") {       // ['return', expr, ';']
            return ast_return(emit_expr_str(vec_get(s.children, 1)));
        }
        if streq(first.text, "if") {           // ['if', '(', expr, ')', stmt, elses]
            var cond *u8 = emit_expr_str(vec_get(s.children, 2));
            var then_b *u8 = emit_stmt_as_block(vec_get(s.children, 4));
            var elses *PNode = vec_get(s.children, 5);   // c_elses = c_elsepart*
            var else_b *u8 = nil;
            if vec_len(elses.children) > 0 {
                var elsepart *PNode = vec_get(elses.children, 0);  // ['else', stmt]
                else_b = emit_stmt_as_block(vec_get(elsepart.children, 1));
            }
            return ast_if(cond, then_b, else_b);
        }
        if streq(first.text, "while") {        // ['while', '(', expr, ')', stmt]
            return ast_while(emit_expr_str(vec_get(s.children, 2)),
                             emit_stmt_as_block(vec_get(s.children, 4)));
        }
        if streq(first.text, "for") {
            return emit_for(s);
        }
        if streq(first.text, "switch") {
            return emit_switch(s);
        }
    }

    // first is a kind-4 list: a c_decl leads with a c_ptype, whose first child
    // (the anytype) is either a base-type keyword (kind 2: int/char/void) or a
    // c_structtype = ['struct', Name] (kind 4). A c_exprstmt leads with a c_expr,
    // whose first child is a c_unary (kind 4) - never a 'struct'-led structtype.
    var f0 *PNode = vec_get(first.children, 0);
    if f0.kind == 2 {
        if streq(f0.text, "int") || streq(f0.text, "char") || streq(f0.text, "void") {
            return emit_decl(s);
        }
    }
    if f0.kind == 4 {
        var g0 *PNode = vec_get(f0.children, 0);
        if g0.kind == 2 {
            if streq(g0.text, "struct") { return emit_decl(s); }   // struct-typed local
            if streq(g0.text, "enum") { return emit_decl(s); }     // enum-typed local
        }
    }
    return emit_exprstmt_from_expr(first);
}

// Base operator for a compound-assignment op ("+=" -> "+", ...); nil otherwise.
func compound_base(op *u8) *u8 {
    if streq(op, "+=") { return "+"; }
    if streq(op, "-=") { return "-"; }
    if streq(op, "*=") { return "*"; }
    if streq(op, "/=") { return "/"; }
    if streq(op, "%=") { return "%"; }
    return nil;
}

// Base operator for an increment/decrement op ("++" -> "+", "--" -> "-"); nil otherwise.
func incdec_base(op *u8) *u8 {
    if streq(op, "++") { return "+"; }
    if streq(op, "--") { return "-"; }
    return nil;
}

// Emit `lv = lv <base> 1` for a ++/-- statement (lvnode is a c_unary/c_postfix).
func emit_incdec(lvnode *PNode, base *u8) *u8 {
    var lv *u8 = emit_operand_str(lvnode);
    return ast_assign(lv, ast_binop(base, lv, ast_int(1)));
}

// Handle ++/-- used as a whole statement (or for-step): postfix `i++` / `i--`
// (one oprest that is a bare op) or prefix `++i` / `--i` (a c_neg with op ++/--).
// Returns the assign string if handled, else nil. ++/-- in value position is NOT
// handled here (see climb).
func try_incdec(expr *PNode) *u8 {
    var u *PNode = vec_get(expr.children, 0);        // c_unary
    var star *PNode = vec_get(expr.children, 1);     // c_oprest*
    var ns i64 = vec_len(star.children);
    if ns == 1 {                                     // postfix: lvalue ++ / --
        var orn *PNode = vec_get(star.children, 0);
        if vec_len(orn.children) == 1 {              // bare op, no right operand
            var opn *PNode = vec_get(orn.children, 0);
            var base *u8 = incdec_base(opn.text);
            if base != nil { return emit_incdec(u, base); }
        }
    }
    if ns == 0 {                                     // prefix: ++ / -- lvalue
        var u0 *PNode = vec_get(u.children, 0);
        if u0.kind == 5 {
            var base *u8 = incdec_base(u0.text);
            if base != nil { return emit_incdec(vec_get(u.children, 1), base); }
        }
    }
    return nil;
}

// Lower a bare c_expr as a statement: ++/-- desugar to an assignment, a leading
// '=' is a plain assignment, a leading compound op (+=, ...) desugars to
// `lv = lv op rhs`, otherwise an expression statement. Shared by exprstmt and the
// for-loop step (a bare expr with no trailing ';').
func emit_exprstmt_from_expr(expr *PNode) *u8 {
    var binexpr *PNode = vec_get(expr.children, 0);   // c_expr = [c_binexpr, terntail*]
    var terntail *PNode = vec_get(expr.children, 1);
    var ntt i64 = vec_len(terntail.children);
    if ntt == 0 {                                     // ++/-- only on a bare lvalue
        var inc *u8 = try_incdec(binexpr);
        if inc != nil { return inc; }
    }
    var operands *u8 = vec_new(8);
    var ops *u8 = vec_new(8);
    flatten_expr(binexpr, operands, ops);
    if vec_len(ops) > 0 {
        var op0 *PNode = vec_get(ops, 0);
        if streq(op0.text, "=") {
            var lv *PNode = vec_get(operands, 0);
            var rpos i64 = 1;
            var rhs *u8 = climb(operands, ops, &rpos, 1);         // value right of '=' ...
            if ntt > 0 { rhs = emit_ternary(rhs, vec_get(terntail.children, 0)); }  // ... incl. ?:
            return ast_assign(emit_operand_str(lv), rhs);
        }
        var cbase *u8 = compound_base(op0.text);                  // x op= rhs -> x = x op (rhs)
        if cbase != nil {
            var lv *PNode = vec_get(operands, 0);
            var lvs *u8 = emit_operand_str(lv);
            var cpos i64 = 1;
            var rhs *u8 = climb(operands, ops, &cpos, 1);
            if ntt > 0 { rhs = emit_ternary(rhs, vec_get(terntail.children, 0)); }
            return ast_assign(lvs, ast_binop(cbase, lvs, rhs));
        }
    }
    var epos i64 = 0;
    var base *u8 = climb(operands, ops, &epos, 0);
    if ntt > 0 { base = emit_ternary(base, vec_get(terntail.children, 0)); }
    return ast_expr_stmt(base);
}

// c_forstmt = 'for' '(' c_forinit c_expr ';' c_expr ')' c_stmt
//   children: [for, (, init, cond, ;, step, ), body]   (init consumes its ';')
// Desugar to a block: { init; while (cond) { body; step; } }.  (continue inside
// the body skips step - an accepted limitation of this bounded subset.)
func emit_for(s *PNode) *u8 {
    var init *PNode = vec_get(s.children, 2);
    var cond *PNode = vec_get(s.children, 3);
    var step *PNode = vec_get(s.children, 5);
    var body *PNode = vec_get(s.children, 7);
    var inner *u8 = ast_vec();
    ast_push(inner, emit_stmt(body));
    ast_push(inner, emit_exprstmt_from_expr(step));
    var outer *u8 = ast_vec();
    ast_push(outer, emit_stmt(init));                       // decl or assignment (handles both)
    ast_push(outer, ast_while(emit_expr_str(cond), ast_block(inner)));
    return ast_block(outer);
}

// A c_switchitem is a 'case' label, a 'default' label, or a statement. Return
// 1=case, 2=default, 0=statement (by the item's leading atom).
func switch_label_kind(it *PNode) i64 {
    var h *PNode = vec_get(it.children, 0);
    if h.kind == 2 {
        if streq(h.text, "case") { return 1; }
        if streq(h.text, "default") { return 2; }
    }
    return 0;
}

func switch_is_break(it *PNode) i64 {
    var h *PNode = vec_get(it.children, 0);
    if h.kind == 2 {
        if streq(h.text, "break") { return 1; }
    }
    return 0;
}

// Finalize one case group: build its condition (svname == v1 || svname == v2 ...,
// or nil for `default`) and body block, appending both to the parallel conds/bodies.
func switch_finalize(conds *u8, bodies *u8, svname *u8, vals *u8, is_default i64, body *u8) void {
    var cond *u8 = nil;
    if is_default == 0 {
        var nv i64 = vec_len(vals);
        var j i64 = 0;
        while j < nv {
            var eq *u8 = ast_binop("==", ast_ident(svname), vec_get(vals, j));
            if cond == nil { cond = eq; }
            else { cond = ast_binop("||", cond, eq); }
            j = j + 1;
        }
    }
    vec_push(conds, cond);          // nil marks the default group
    vec_push(bodies, ast_block(body));
}

// switch (E) { case V: ... } -> evaluate E once into a temp, then an if/else-if
// chain (one arm per case group; `default` is the final else). BOUNDED: each
// case is independent - there is NO fall-through (a case body without break does
// not flow into the next). Stacked empty labels (case 2: case 3:) share one body.
// A top-level break just terminates its case (it is the idiomatic terminator).
//   c_switchstmt = ['switch','(',expr,')','{', items, '}']  -> children[2]=expr, [5]=items
func emit_switch(s *PNode) *u8 {
    var svname *u8 = c_gensym("__sw", s);
    var scrut *u8 = emit_expr_str(vec_get(s.children, 2));
    var items *PNode = vec_get(s.children, 5);
    var n i64 = vec_len(items.children);

    var conds *u8 = vec_new(8);     // per group: condition string (nil = default)
    var bodies *u8 = vec_new(8);    // per group: body block string

    var pend_vals *u8 = ast_vec();  // case-value expr strings for the current stacked labels
    var pend_default i64 = 0;
    var pend_body *u8 = ast_vec();
    var have_body i64 = 0;          // current group has started collecting body statements?
    var have_group i64 = 0;         // any label seen for the current group?

    var i i64 = 0;
    while i < n {
        var it *PNode = vec_get(items.children, i);
        var lab i64 = switch_label_kind(it);
        if lab != 0 {
            if have_body != 0 {     // a label after a body => finalize the previous group
                switch_finalize(conds, bodies, svname, pend_vals, pend_default, pend_body);
                pend_vals = ast_vec(); pend_default = 0; pend_body = ast_vec(); have_body = 0;
            }
            have_group = 1;
            if lab == 2 { pend_default = 1; }
            else { ast_push(pend_vals, emit_expr_str(vec_get(it.children, 1))); }  // case VALUE
        } else {
            if switch_is_break(it) == 0 {       // drop the case-terminating break
                ast_push(pend_body, emit_stmt(it));
            }
            have_body = 1;
        }
        i = i + 1;
    }
    if have_group != 0 {
        switch_finalize(conds, bodies, svname, pend_vals, pend_default, pend_body);
    }

    // Assemble: default body is the innermost else; case arms wrap it (reverse order).
    var else_branch *u8 = nil;
    var ng i64 = vec_len(conds);
    var k i64 = 0;
    while k < ng {
        if vec_get(conds, k) == nil { else_branch = vec_get(bodies, k); }
        k = k + 1;
    }
    var idx i64 = ng - 1;
    while idx >= 0 {
        var c *u8 = vec_get(conds, idx);
        if c != nil { else_branch = ast_if(c, vec_get(bodies, idx), else_branch); }
        idx = idx - 1;
    }

    var stmts *u8 = ast_vec();
    ast_push(stmts, ast_var(svname, ast_type_i64(), scrut));
    if else_branch != nil { ast_push(stmts, else_branch); }
    return ast_block(stmts);
}

// (var NAME TYPE INIT?). arrdim is a c_dim* (zero = scalar; one c_dim =
// ['[', number, ']'] = 1-D array `T[N]` -> (type_array N ELEM), no initializer).
// initopt is the stable-slot optional init for scalars (absent -> no store, as in
// C / a top-level zero). Shared by local decls and globals.
func emit_var(name *PNode, typenode *PNode, arrdim *PNode, initopt *PNode) *u8 {
    if vec_len(arrdim.children) > 0 {
        var dim0 *PNode = vec_get(arrdim.children, 0);   // c_dim = ['[', number, ']']
        var sizenode *PNode = vec_get(dim0.children, 1);
        return ast_var(name.text, ast_type_array(sizenode.text, emit_type(typenode)), nil);
    }
    if vec_len(initopt.children) > 0 {
        var initval *PNode = vec_get(initopt.children, 0);   // ['=', expr]
        return ast_var(name.text, emit_type(typenode), emit_expr_str(vec_get(initval.children, 1)));
    }
    return ast_var(name.text, emit_type(typenode), nil);
}

// c_decl = ptype symbol arrdim initopt ';'  ->  children [ptype, name, arrdim, initopt, ';']
func emit_decl(d *PNode) *u8 {
    var kids *u8 = d.children;
    return emit_var(vec_get(kids, 1), vec_get(kids, 0), vec_get(kids, 2), vec_get(kids, 3));
}

// A control-flow body must be a block; wrap a single statement if needed.
func emit_stmt_as_block(s *PNode) *u8 {
    var first *PNode = vec_get(s.children, 0);
    if first.kind == 0 {           // already a block
        return emit_block(s);
    }
    return ast_block1(emit_stmt(s));
}

func emit_block(block *PNode) *u8 {
    var stmts *u8 = ast_vec();
    if block != nil {
        var sl *PNode = vec_get(block.children, 1);  // ['{', stmt_star, '}']
        var n i64 = vec_len(sl.children);
        var i i64 = 0;
        while i < n {
            ast_push(stmts, emit_stmt(vec_get(sl.children, i)));
            i = i + 1;
        }
    }
    return ast_block(stmts);
}

// ============================================================
// Declarations
// ============================================================

// c_ptype/c_rettype = anytype c_stars  ->  children [anytype, stars_star]. Each
// star wraps the base in a (type_ptr ...). anytype is either a base-type keyword
// atom (kind 2) or a c_structtype = ['struct', Name] (kind 4). char -> u8 so
// `char*` is `*u8` (lang's string type); int -> i64; void -> void; struct N -> N.
func emit_type(t *PNode) *u8 {
    if t == nil { return ast_type("i64"); }
    var anytype *PNode = vec_get(t.children, 0);
    var stars *PNode = vec_get(t.children, 1);
    var n i64 = vec_len(stars.children);
    var base *u8 = nil;
    if anytype.kind == 4 {                        // c_structtype or c_enumtype = [kw, Name]
        var head *PNode = vec_get(anytype.children, 0);
        if streq(head.text, "enum") {
            base = ast_type("i64");               // `enum Name` is just an int
        } else {                                  // c_structtype = ['struct', Name]
            var nm *PNode = vec_get(anytype.children, 1);
            base = ast_type(nm.text);
        }
    } else if streq(anytype.text, "void") {
        base = ast_type("void");
    } else if streq(anytype.text, "char") {
        base = ast_type("u8");
    } else {
        base = ast_type("i64");
    }
    var i i64 = 0;
    while i < n { base = ast_type_ptr(base); i = i + 1; }
    return base;
}

// topvar = c_rettype symbol c_topvartail  ->  children [rettype, name, tail].
// For a function the tail is c_functail = '(' c_params ')' c_block.
func emit_func(tv *PNode) *u8 {
    var rettype *PNode = vec_get(tv.children, 0);
    var name *PNode = vec_get(tv.children, 1);
    var tail *PNode = vec_get(tv.children, 2);     // c_functail = ['(', params, ')', block]
    var params *PNode = vec_get(tail.children, 1);
    var body *PNode = vec_get(tail.children, 3);
    return ast_func(name.text, emit_params(params), emit_type(rettype), emit_block(body));
}

// topvar whose tail is c_globaltail = c_arrdim c_initopt ';'  ->  a global (var ...).
func emit_global(tv *PNode) *u8 {
    var rettype *PNode = vec_get(tv.children, 0);
    var name *PNode = vec_get(tv.children, 1);
    var tail *PNode = vec_get(tv.children, 2);     // c_globaltail = [arrdim, initopt, ';']
    return emit_var(name, rettype, vec_get(tail.children, 0), vec_get(tail.children, 1));
}

// params = paramitem* ; paramitem = param | ',' ; param = type symbol
// Returns a vec of (param name type) for ast_func.
func emit_params(params *PNode) *u8 {
    var pv *u8 = ast_vec();
    if params == nil { return pv; }
    var items *u8 = params.children;
    var n i64 = vec_len(items);
    var i i64 = 0;
    while i < n {
        var it *PNode = vec_get(items, i);
        if it.kind == 4 {                  // a param (kind-0 = ',' marker)
            var pkids *u8 = it.children;
            var pname *PNode = vec_get(pkids, 1);   // bind before .text: vec_get is *u8
            var ptype *PNode = vec_get(pkids, 0);
            ast_push(pv, ast_param(pname.text, emit_type(ptype)));
        }
        i = i + 1;
    }
    return pv;
}

// Parse a non-negative decimal integer from text (enum value literals).
func c_atoi(s *u8) i64 {
    var n i64 = 0;
    var i i64 = 0;
    while *(s + i) != 0 {
        var c i64 = *(s + i);
        if c >= 48 {
            if c <= 57 { n = n * 10 + (c - 48); }
        }
        i = i + 1;
    }
    return n;
}

// c_enumdef = 'enum' tag '{' c_enumitems '}' ';'  ->  children [enum, tag, '{',
// items, '}', ';'].  Each member becomes a global int constant (var NAME i64 V);
// implicit values count up from 0 (or from the last explicit value + 1), so
// `enum { A, B, C }` is 0/1/2 and `enum { X = 10, Y }` is 10/11. The tag name is
// cosmetic (the kernel has no enum type; `enum Tag` lowers to i64 in emit_type).
func emit_enumdef(d *PNode, decls *u8) void {
    var items *PNode = vec_get(d.children, 3);     // c_enumitems = c_enumitem*
    var n i64 = vec_len(items.children);
    var counter i64 = 0;
    var i i64 = 0;
    while i < n {
        var it *PNode = vec_get(items.children, i);   // c_enumitem = member | ','
        if it.kind == 4 {                              // a member (',' is a kind-0 marker)
            var namep *PNode = vec_get(it.children, 0);    // bind before .text: vec_get is *u8
            var valopt *PNode = vec_get(it.children, 1);   // c_enumvalopt = c_enumval*
            var value i64 = counter;
            if vec_len(valopt.children) > 0 {
                var ev *PNode = vec_get(valopt.children, 0);   // c_enumval = ['=', number]
                var numn *PNode = vec_get(ev.children, 1);
                value = c_atoi(numn.text);
            }
            ast_push(decls, ast_var(namep.text, ast_type_i64(), ast_int(value)));
            counter = value + 1;
        }
        i = i + 1;
    }
}

// c_structdef = 'struct' Name '{' c_fields '}' ';'  ->  children [struct, Name,
// '{', fields, '}', ';'].  Each c_field = c_ptype symbol ';'.
func emit_structdef(sd *PNode) *u8 {
    var name *PNode = vec_get(sd.children, 1);
    var fields *PNode = vec_get(sd.children, 3);
    var fv *u8 = ast_vec();
    var n i64 = vec_len(fields.children);
    var i i64 = 0;
    while i < n {
        var fld *PNode = vec_get(fields.children, i);     // c_field = [ptype, name, ';']
        var fname *PNode = vec_get(fld.children, 1);      // bind before .text: vec_get is *u8
        var ftype *PNode = vec_get(fld.children, 0);
        ast_push(fv, ast_field_decl(fname.text, emit_type(ftype)));
        i = i + 1;
    }
    return ast_struct(name.text, fv);
}

// program = topdecl+ ; topdecl = structdef | topvar. A structdef leads with the
// 'struct' keyword (kind-2 atom); a topvar leads with its c_rettype (kind-4 list).
// A topvar's tail picks func vs global: c_functail leads with a '(' marker
// (kind 0), c_globaltail leads with c_arrdim (a kind-4 star list).
func emit_program(prog *PNode) *u8 {
    var decls *u8 = ast_vec();
    if prog != nil {
        var dl *u8 = prog.children;
        var n i64 = vec_len(dl);
        var i i64 = 0;
        while i < n {
            var d *PNode = vec_get(dl, i);
            var head *PNode = vec_get(d.children, 0);
            if head.kind == 2 && streq(head.text, "struct") {
                ast_push(decls, emit_structdef(d));
            } else if head.kind == 2 && streq(head.text, "enum") {
                emit_enumdef(d, decls);                     // pushes one global per member
            } else {
                var tail *PNode = vec_get(d.children, 2);   // c_topvartail
                var t0 *PNode = vec_get(tail.children, 0);
                if t0.kind == 0 {                           // '(' marker -> function
                    ast_push(decls, emit_func(d));
                } else {                                    // c_arrdim -> global var
                    ast_push(decls, emit_global(d));
                }
            }
            i = i + 1;
        }
    }
    return ast_program(decls);
}

reader c(text *u8) *u8 {
    var t *Tokenizer = tok_new(text);
    var prog *PNode = parse_c_program(t);
    return emit_program(prog);
}

example/forth/forth.lang:
// ============================================================
// forth - a stack language whose stack vanishes at compile time
// ============================================================
//
// The fourth polyglot language, and the one furthest from the other three. C,
// minilisp and flow all have an expression grammar; Forth has none. A Forth
// program is a flat stream of whitespace-separated words that push and pop a
// data stack, and control flow is just more words:
//
//   #forth{
//       : square ( n -- n2 ) dup * ;
//       : fact   ( n -- f )  dup 2 < if drop 1 else dup 1 - recurse * then ;
//   }
//
// There is NO data stack in the generated code. The reader keeps a stack of AST
// NODES while it walks the word stream: `dup` duplicates a node, `*` pops two
// and pushes `(binop * a b)`. By `;` the stack holds the word's result and every
// trace of the stack is gone - `square` compiles to exactly the same native code
// as `func square(n i64) i64 { return n * n; }`. This mirrors how a real Forth
// compiles `if`/`then` with a compile-time control stack, except we erase the
// data stack too.
//
// The stack effect comment is LOAD-BEARING here (in real Forth it is a comment):
// `( a b -- s )` names the parameters and counts the results, which is what lets
// a word become an ordinary i64 lang function callable from C, Lisp, flow and
// lang - and lets them be called back from Forth.
//
// Words:
//   : n ( ... ) ... ;   define        extern n ( ... ) ;   import a host function
//   + - * / mod         arithmetic    = <> < > <= >=       comparison (flag 0/1)
//   and or xor invert   bitwise       negate               unary minus
//   dup drop swap over nip rot        stack shuffling
//   if ... else ... then              conditional
//   recurse             self-call     .  cr                output (see runtime)
//
// Deliberate bounds (round 1): no loops (`begin`/`do`) and no `variable`/`!`/`@`,
// so a word body stays a pure expression tree and recursion is the only
// repetition. Word names must be lang identifiers plus an optional trailing `?`
// (`prime?` mangles to `prime_p`) - the shared tokenizer lexes `-` as an
// operator, so `is-prime` can't be a name. Negative literals must be written
// `0 5 -` or `5 negate`; the tokenizer splits `-5` into two words. Comments are
// `( ... )` (or lang's `//`), not `\`.
//
// Evaluation order is preserved exactly: before any word that duplicates,
// reorders, discards or emits a statement, every impure node still sitting on
// the compile-time stack is materialized into a temp (see fo_flush). Otherwise
// deferring an unevaluated call past a `.` would silently reorder side effects.
//
// Converter helpers are fo_-prefixed so forth composes with the C, minilisp and
// flow readers in one binary (no symbol collisions).

include "std/core.lang"
include "std/tok.lang"
include "std/parser_reader.lang"
include "std/ast.lang"

// The grammar is almost nothing - which is the point. A body is a FLAT word
// list; `if`/`else`/`then` are ordinary words that the converter gives meaning
// to, exactly as Forth does with immediate words. There is deliberately no
// expression grammar: nesting is meaning assigned later by the reader.
#parser{
    fo_program   = fo_def+
    fo_def       = fo_worddef | fo_externdef | fo_effect
    fo_worddef   = ':' fo_name fo_effect fo_body ';'
    fo_externdef = 'extern' fo_name fo_effect ';'
    fo_name      = symbol fo_qmark*
    fo_qmark     = '?'
    fo_effect    = '(' fo_eitem* ')'
    fo_eitem     = symbol | operator | number
    fo_body      = fo_word*
    fo_word      = fo_name | number | operator | fo_effect | '.'
}

// PNode kinds: 0=literal marker (carries its text), 1=number, 2=symbol,
// 4=list/seq, 5=operator.

// ============================================================
// Comments
// ============================================================

func fo_word_char(c i64) i64 {
    if c >= 48 && c <= 57 { return 1; }         // 0-9
    if c >= 65 && c <= 90 { return 1; }         // A-Z
    if c >= 97 && c <= 122 { return 1; }        // a-z
    if c == 95 { return 1; }                    // _
    if c == 45 { return 1; }                    // -  (keeps the `--` separator)
    return 0;
}

// A Forth comment is `( ... )` and, being a comment, may contain anything at
// all - but the shared tokenizer would choke on a `:` or a quote inside one and
// silently derail the parse. Real Forth never tokenizes a comment's contents;
// we can't skip them entirely (the stack effect wears the same parentheses and
// IS parsed), so instead sanitize every parenthesized interior down to word
// characters. A comment can then say what it likes, while a stack effect - just
// names plus the `--` separator - still reads exactly as before.
//
// `//` line comments are passed through untouched (the tokenizer strips them),
// so a `(` inside one can't be mistaken for the start of a Forth comment.
func fo_sanitize_comments(text *u8) *u8 {
    var sb *StringBuilder = sb_new();
    var p *u8 = text;
    var depth i64 = 0;
    while *p != 0 {
        var c i64 = *p;
        if depth == 1 {
            if c == 41 {                        // )
                depth = 0;
                sb_char(sb, c);
            } else if fo_word_char(c) == 1 {
                sb_char(sb, c);
            } else {
                sb_char(sb, 32);
            }
        } else if c == 40 {                     // (
            depth = 1;
            sb_char(sb, c);
        } else if c == 47 && *(p + 1) == 47 {   // //
            while *p != 0 && *p != 10 {
                sb_char(sb, *p);
                p = p + 1;
            }
            if *p == 0 { return sb_finish(sb); }
            sb_char(sb, *p);
        } else {
            sb_char(sb, c);
        }
        p = p + 1;
    }
    return sb_finish(sb);
}

// ============================================================
// Names and stack effects
// ============================================================

// fo_name = symbol fo_qmark*. Forth loves `?` in names (`prime?`); lang has no
// such identifier, so each trailing `?` becomes `_p`.
func fo_name_text(n *PNode) *u8 {
    var sym *PNode = vec_get(n.children, 0);
    var qs *PNode = vec_get(n.children, 1);
    var nq i64 = vec_len(qs.children);
    if nq == 0 { return sym.text; }
    var sb *StringBuilder = sb_new();
    sb_str(sb, sym.text);
    var i i64 = 0;
    while i < nq {
        sb_str(sb, "_p");
        i = i + 1;
    }
    return sb_finish(sb);
}

// The word at index i, if it is a name word (else nil) - for peeking at the
// `else`/`then` terminators without consuming them.
func fo_word_at(items *u8, i i64) *u8 {
    if i >= vec_len(items) { return nil; }
    var it *PNode = vec_get(items, i);
    if it.kind != 4 { return nil; }
    var head *PNode = vec_get(it.children, 0);
    if head.kind != 2 { return nil; }
    return fo_name_text(it);
}

// `( a b -- s )` -> push "a","b" onto pnames, return the result count. The `--`
// arrives as a single 2-char operator atom (the tokenizer lexes it for C's `--`).
func fo_effect_split(eff *PNode, pnames *u8) i64 {
    var star *PNode = vec_get(eff.children, 1);
    var items *u8 = star.children;
    var n i64 = vec_len(items);
    var past i64 = 0;
    var nres i64 = 0;
    var i i64 = 0;
    while i < n {
        var it *PNode = vec_get(items, i);
        if it.kind == 5 {
            if streq(it.text, "--") { past = 1; }
        } else if it.kind == 2 {
            if past == 1 {
                nres = nres + 1;
            } else {
                vec_push(pnames, it.text);
            }
        }
        i = i + 1;
    }
    if past == 0 {
        eprint("forth: stack effect is missing '--'; treating every name as a parameter\n");
    }
    return nres;
}

// A top-level item is a `:` definition (1), an `extern` declaration (2), or a
// bare ( ... ) comment between definitions (0).
func fo_def_kind(d *PNode) i64 {
    var head *PNode = vec_get(d.children, 0);
    if head.kind == 2 { return 2; }             // the 'extern' keyword
    if streq(head.text, ":") == 1 { return 1; }
    return 0;
}

// Signatures are a flat vec of (name, nparams, nresults) triples, collected in a
// pre-pass and threaded as a parameter - a module-level global declared in a
// reader's own file is silently dropped by the reader-build path.
func fo_collect_sigs(prog *PNode) *u8 {
    var sigs *u8 = vec_new(24);
    var defs *u8 = prog.children;
    var n i64 = vec_len(defs);
    var i i64 = 0;
    while i < n {
        var d *PNode = vec_get(defs, i);
        if fo_def_kind(d) == 0 {
            i = i + 1;
            continue;
        }
        var namen *PNode = vec_get(d.children, 1);
        var eff *PNode = vec_get(d.children, 2);
        var pnames *u8 = vec_new(8);
        var nres i64 = fo_effect_split(eff, pnames);
        vec_push(sigs, fo_name_text(namen));
        vec_push(sigs, vec_len(pnames));
        vec_push(sigs, nres);
        i = i + 1;
    }
    return sigs;
}

func fo_sig_find(sigs *u8, name *u8) i64 {
    var n i64 = vec_len(sigs);
    var i i64 = 0;
    while i < n {
        var nm *u8 = vec_get(sigs, i);
        if streq(nm, name) { return i; }
        i = i + 3;
    }
    return 0 - 1;
}

// ============================================================
// The compile-time stack (of AST nodes)
// ============================================================

func fo_pop(stack *u8) *u8 {
    if vec_len(stack) == 0 {
        eprint("forth: stack underflow\n");
        return ast_int(0);
    }
    return vec_pop(stack);
}

func fo_stack_copy(src *u8) *u8 {
    var d *u8 = vec_new(16);
    var n i64 = vec_len(src);
    var i i64 = 0;
    while i < n {
        vec_push(d, vec_get(src, i));
        i = i + 1;
    }
    return d;
}

func fo_stack_load(dst *u8, src *u8) void {
    while vec_len(dst) > 0 { vec_pop(dst); }
    var n i64 = vec_len(src);
    var i i64 = 0;
    while i < n {
        vec_push(dst, vec_get(src, i));
        i = i + 1;
    }
}

// Per-node-unique temp name (reader globals are dropped, so derive uniqueness
// from the node address plus a slot tag).
func fo_gensym(prefix *u8, node *PNode, tag i64) *u8 {
    var sb *StringBuilder = sb_new();
    sb_str(sb, prefix);
    var addr i64 = node;
    sb_int(sb, addr);
    sb_str(sb, "_");
    sb_int(sb, tag);
    return sb_finish(sb);
}

func fo_starts(s *u8, p *u8) i64 {
    while *p != 0 {
        if *s == 0 { return 0; }
        if *s != *p { return 0; }
        s = s + 1;
        p = p + 1;
    }
    return 1;
}

// A node is "simple" when re-evaluating it or deferring it past a statement is
// free of consequence: a literal or a bare variable reference.
func fo_is_simple(e *u8) i64 {
    if fo_starts(e, "(number ") == 1 { return 1; }
    if fo_starts(e, "(ident ") == 1 { return 1; }
    return 0;
}

// Force every pending computation on the stack into a temp, bottom-up, so it
// happens HERE. Called before any word that duplicates, reorders, discards or
// emits a statement - without it, `f g 42 . *` would emit the print before f and
// g ran, quietly reordering side effects relative to real Forth.
func fo_flush_upto(stack *u8, stmts *u8, node *PNode, limit i64) void {
    var n i64 = limit;
    var i i64 = 0;
    while i < n {
        var e *u8 = vec_get(stack, i);
        if fo_is_simple(e) == 0 {
            var t *u8 = fo_gensym("__fs", node, i);
            ast_push(stmts, ast_var(t, ast_type_i64(), e));
            vec_set(stack, i, ast_ident(t));
        }
        i = i + 1;
    }
}

func fo_flush(stack *u8, stmts *u8, node *PNode) void {
    fo_flush_upto(stack, stmts, node, vec_len(stack));
}

// ============================================================
// Words
// ============================================================

func fo_binop_for(op *u8) *u8 {
    if streq(op, "=")  { return "=="; }     // Forth's `=` is a comparison
    if streq(op, "+")  { return "+"; }
    if streq(op, "-")  { return "-"; }
    if streq(op, "*")  { return "*"; }
    if streq(op, "/")  { return "/"; }
    if streq(op, "%")  { return "%"; }
    if streq(op, "<")  { return "<"; }
    if streq(op, ">")  { return ">"; }
    if streq(op, "<=") { return "<="; }
    if streq(op, ">=") { return ">="; }
    return nil;
}

// ( a b -- a OP b ). No flush: operands are popped in Forth's own order, and
// lang evaluates a binop left-to-right, so the order already matches.
func fo_binary(stack *u8, op *u8) void {
    var b *u8 = fo_pop(stack);
    var a *u8 = fo_pop(stack);
    vec_push(stack, ast_binop(op, a, b));
}

func fo_emit_operator(items *u8, ip *i64, stack *u8) void {
    var op *PNode = vec_get(items, *ip);
    var text *u8 = op.text;
    *ip = *ip + 1;
    // Forth's not-equal is `<>`; the tokenizer hands us two separate operators.
    if streq(text, "<") {
        var nxt *PNode = nil;
        if *ip < vec_len(items) { nxt = vec_get(items, *ip); }
        if nxt != nil {
            if nxt.kind == 5 {
                if streq(nxt.text, ">") {
                    *ip = *ip + 1;
                    fo_binary(stack, "!=");
                    return;
                }
            }
        }
    }
    var lop *u8 = fo_binop_for(text);
    if lop == nil {
        eprint("forth: unknown operator word '");
        eprint(text);
        eprint("'\n");
        return;
    }
    fo_binary(stack, lop);
}

// dup/over duplicate a node, so what they duplicate must already be a value.
func fo_shuffle(w *u8, stack *u8, stmts *u8, node *PNode) i64 {
    fo_flush(stack, stmts, node);
    var n i64 = vec_len(stack);
    if streq(w, "dup") {
        if n < 1 { eprint("forth: dup on an empty stack\n"); return 1; }
        vec_push(stack, vec_get(stack, n - 1));
        return 1;
    }
    if streq(w, "drop") {
        if n < 1 { eprint("forth: drop on an empty stack\n"); return 1; }
        vec_pop(stack);
        return 1;
    }
    if streq(w, "swap") {
        if n < 2 { eprint("forth: swap needs two values\n"); return 1; }
        var a *u8 = vec_get(stack, n - 2);
        var b *u8 = vec_get(stack, n - 1);
        vec_set(stack, n - 2, b);
        vec_set(stack, n - 1, a);
        return 1;
    }
    if streq(w, "over") {
        if n < 2 { eprint("forth: over needs two values\n"); return 1; }
        vec_push(stack, vec_get(stack, n - 2));
        return 1;
    }
    if streq(w, "nip") {
        if n < 2 { eprint("forth: nip needs two values\n"); return 1; }
        var top *u8 = vec_get(stack, n - 1);
        vec_pop(stack);
        vec_set(stack, n - 2, top);
        return 1;
    }
    if streq(w, "rot") {
        if n < 3 { eprint("forth: rot needs three values\n"); return 1; }
        var x *u8 = vec_get(stack, n - 3);
        var y *u8 = vec_get(stack, n - 2);
        var z *u8 = vec_get(stack, n - 1);
        vec_set(stack, n - 3, y);
        vec_set(stack, n - 2, z);
        vec_set(stack, n - 1, x);
        return 1;
    }
    return 0;
}

// A call to a defined word, an extern host function, or `recurse`.
func fo_emit_call(name *u8, stack *u8, stmts *u8, sigs *u8, node *PNode) void {
    var si i64 = fo_sig_find(sigs, name);
    if si < 0 {
        eprint("forth: undefined word '");
        eprint(name);
        eprint("' (declare host functions with `extern name ( a -- r ) ;`)\n");
        vec_push(stack, ast_int(0));
        return;
    }
    var np i64 = vec_get(sigs, si + 1);
    var nr i64 = vec_get(sigs, si + 2);
    // A word that returns nothing becomes a statement, so pending work on the
    // stack has to happen first.
    if nr == 0 { fo_flush(stack, stmts, node); }

    var popped *u8 = vec_new(8);
    var k i64 = 0;
    while k < np {
        vec_push(popped, fo_pop(stack));
        k = k + 1;
    }
    var args *u8 = ast_vec();
    k = np - 1;
    while k >= 0 {
        ast_push(args, vec_get(popped, k));
        k = k - 1;
    }
    var call *u8 = ast_call_named(name, args);
    if nr == 0 {
        ast_push(stmts, ast_expr_stmt(call));
    } else {
        if nr > 1 {
            eprint("forth: word '");
            eprint(name);
            eprint("' declares more than one result; only the first is kept\n");
        }
        vec_push(stack, call);
    }
}

// ============================================================
// if / else / then
// ============================================================

// The flag is popped, then BOTH branches run on a copy of the same stack. Any
// slot they disagree about becomes a temp assigned in each branch - which is how
// a value-producing conditional falls out of a language that has no conditional
// expression. The condition is evaluated exactly once.
//
// *ip points just past `if` on entry, and just past `then` on exit.
func fo_emit_if(node *PNode, items *u8, ip *i64, stack *u8, stmts *u8, sigs *u8, selfname *u8) void {
    var cond *u8 = fo_pop(stack);
    fo_flush(stack, stmts, node);
    var saved *u8 = fo_stack_copy(stack);

    var then_stmts *u8 = ast_vec();
    fo_emit_seq(items, ip, stack, then_stmts, sigs, selfname);
    var then_stack *u8 = fo_stack_copy(stack);

    var has_else i64 = 0;
    var w *u8 = fo_word_at(items, *ip);
    if w != nil {
        if streq(w, "else") == 1 { has_else = 1; }
    }
    var else_stmts *u8 = ast_vec();
    var else_stack *u8 = saved;
    if has_else == 1 {
        *ip = *ip + 1;
        fo_stack_load(stack, saved);
        fo_emit_seq(items, ip, stack, else_stmts, sigs, selfname);
        else_stack = fo_stack_copy(stack);
    }

    var w2 *u8 = fo_word_at(items, *ip);
    if w2 == nil {
        eprint("forth: `if` without a closing `then`\n");
    } else {
        if streq(w2, "then") {
            *ip = *ip + 1;
        } else {
            eprint("forth: `if` without a closing `then`\n");
        }
    }

    var dt i64 = vec_len(then_stack);
    var de i64 = vec_len(else_stack);
    if dt != de {
        eprint("forth: if/else leave different stack depths; using the shallower one\n");
    }
    var d i64 = dt;
    if de < d { d = de; }

    var result *u8 = vec_new(16);
    var j i64 = 0;
    while j < d {
        var a *u8 = vec_get(then_stack, j);
        var b *u8 = vec_get(else_stack, j);
        if streq(a, b) == 1 {
            vec_push(result, a);
        } else {
            var t *u8 = fo_gensym("__fi", node, j);
            ast_push(stmts, ast_var(t, ast_type_i64(), ast_int(0)));
            ast_push(then_stmts, ast_assign(ast_ident(t), a));
            ast_push(else_stmts, ast_assign(ast_ident(t), b));
            vec_push(result, ast_ident(t));
        }
        j = j + 1;
    }

    var else_block *u8 = nil;
    if ast_vec_len(else_stmts) > 0 { else_block = ast_block(else_stmts); }
    ast_push(stmts, ast_if(cond, ast_block(then_stmts), else_block));
    fo_stack_load(stack, result);
}

// ============================================================
// The word stream
// ============================================================

// Walk words from *ip, stopping AT `else`/`then` (the caller consumes them).
func fo_emit_seq(items *u8, ip *i64, stack *u8, stmts *u8, sigs *u8, selfname *u8) void {
    var n i64 = vec_len(items);
    while *ip < n {
        var it *PNode = vec_get(items, *ip);
        if it.kind == 1 {
            vec_push(stack, ast_number(it.text));
            *ip = *ip + 1;
        } else if it.kind == 5 {
            fo_emit_operator(items, ip, stack);
        } else if it.kind == 0 {
            // `.` - print the top of stack (with Forth's trailing space)
            fo_flush(stack, stmts, it);
            ast_push(stmts, ast_expr_stmt(ast_call_named1("forth_dot", fo_pop(stack))));
            *ip = *ip + 1;
        } else {
            var head *PNode = vec_get(it.children, 0);
            if head.kind == 0 {
                *ip = *ip + 1;                      // an inline ( ... ) comment
            } else {
                var w *u8 = fo_name_text(it);
                if streq(w, "else") == 1 { return; }
                if streq(w, "then") == 1 { return; }
                *ip = *ip + 1;
                fo_emit_word(w, it, items, ip, stack, stmts, sigs, selfname);
            }
        }
    }
}

// One name word. *ip already points past it.
func fo_emit_word(w *u8, node *PNode, items *u8, ip *i64, stack *u8, stmts *u8, sigs *u8, selfname *u8) void {
    if streq(w, "if") == 1 {
        fo_emit_if(node, items, ip, stack, stmts, sigs, selfname);
        return;
    }
    if fo_shuffle(w, stack, stmts, node) == 1 { return; }
    if streq(w, "mod") == 1 { fo_binary(stack, "%"); return; }
    if streq(w, "and") == 1 { fo_binary(stack, "&"); return; }
    if streq(w, "or") == 1  { fo_binary(stack, "|"); return; }
    if streq(w, "xor") == 1 { fo_binary(stack, "^"); return; }
    if streq(w, "negate") == 1 {
        vec_push(stack, ast_neg(fo_pop(stack)));
        return;
    }
    if streq(w, "invert") == 1 {                    // lang has no unary `~`
        vec_push(stack, ast_binop("^", fo_pop(stack), ast_neg(ast_int(1))));
        return;
    }
    if streq(w, "cr") == 1 {
        fo_flush(stack, stmts, node);
        ast_push(stmts, ast_expr_stmt(ast_call_named0("forth_cr")));
        return;
    }
    var target *u8 = w;
    if streq(w, "recurse") == 1 { target = selfname; }
    fo_emit_call(target, stack, stmts, sigs, node);
}

// ============================================================
// Definitions
// ============================================================

// `: name ( a b -- s ) words ;` -> func name(a i64, b i64) i64 { ... }
// The stack starts holding the parameters; whatever is on top at `;` is the
// result. Every word is i64, which is the ABI the other polyglot languages
// speak, so a Forth word is directly callable from C, Lisp, flow and lang.
func fo_emit_worddef(d *PNode, sigs *u8) *u8 {
    var namen *PNode = vec_get(d.children, 1);
    var wname *u8 = fo_name_text(namen);
    var eff *PNode = vec_get(d.children, 2);
    var body *PNode = vec_get(d.children, 3);

    var pnames *u8 = vec_new(8);
    var nres i64 = fo_effect_split(eff, pnames);

    var params *u8 = ast_vec();
    var stack *u8 = vec_new(16);
    var np i64 = vec_len(pnames);
    var i i64 = 0;
    while i < np {
        var pn *u8 = vec_get(pnames, i);
        ast_push(params, ast_param(pn, ast_type_i64()));
        vec_push(stack, ast_ident(pn));
        i = i + 1;
    }

    var stmts *u8 = ast_vec();
    var ip i64 = 0;
    fo_emit_seq(body.children, &ip, stack, stmts, sigs, wname);

    // Anything left BELOW the result is a discarded value whose side effects
    // still have to happen, and happen first. The result itself needs no temp -
    // the return is its evaluation point.
    var depth i64 = vec_len(stack);
    var keep i64 = 0;
    if nres > 0 { keep = 1; }
    fo_flush_upto(stack, stmts, d, depth - keep);
    if nres > 0 {
        if depth > 0 {
            ast_push(stmts, ast_return(vec_get(stack, depth - 1)));
        } else {
            eprint("forth: '");
            eprint(wname);
            eprint("' promises a result but leaves an empty stack\n");
            ast_push(stmts, ast_return(ast_int(0)));
        }
    } else {
        ast_push(stmts, ast_return(ast_int(0)));
    }
    return ast_func(wname, params, ast_type_i64(), ast_block(stmts));
}

// `extern` contributes only a signature (so calls get the right arity); the
// function itself comes from C, Lisp, flow or lang.
func fo_emit_program(prog *PNode) *u8 {
    var sigs *u8 = fo_collect_sigs(prog);
    var decls *u8 = ast_vec();
    var defs *u8 = prog.children;
    var n i64 = vec_len(defs);
    var i i64 = 0;
    while i < n {
        var d *PNode = vec_get(defs, i);
        if fo_def_kind(d) == 1 {
            ast_push(decls, fo_emit_worddef(d, sigs));
        }
        i = i + 1;
    }
    return ast_program(decls);
}

reader forth(text *u8) *u8 {
    var t *Tokenizer = tok_new(fo_sanitize_comments(text));
    var prog *PNode = parse_fo_program(t);
    return fo_emit_program(prog);
}

example/minilisp/minilisp.lang:
// ============================================================
// minilisp - a small but real Lisp that compiles to a native binary
// ============================================================
//
// Reads s-expression syntax via #parser{} (Level 3) and lowers it to lang AST
// with the std/ast.lang builder API (Level 1) - NO hand-written S-expr strings.
//
// Values are BOXED: every Lisp value is an i64 that is really a *LispObj pointer
// (see example/minilisp/lisp_runtime.lang). So lists are first-class. Programs
// using #minilisp{} must `include "example/minilisp/lisp_runtime.lang"`, and
// cross-language calls marshal with lisp_int(...) / lisp_to_int(...).
//
// EXPRESSIONS:
//   (+ 1 2)  (* 2 (+ 3 4))  (< x 0)  (if c t e)  (and a b) (or a b) (not x)
//   (cons 1 (cons 2 nil))  (car xs)  (cdr xs)  (list 1 2 3)  (eq a b)
//   (quote (a b c))  (let ((x 1) (y 2)) body)
//   (lambda (x) (+ x 1))  (funcall f a b)  (apply f arglist)  ((lambda (x) x) 5)
// DEFINITIONS:
//   (defun add (a b) (+ a b))
//   (defun len (xs) (if (eq xs nil) 0 (+ 1 (len (cdr xs)))))
//   (defun map (f xs) (if (eq xs nil) nil (cons (funcall f (car xs)) (map f (cdr xs)))))
//
// Lisp-2: (f x) calls the function NAMED f (a defun); to call a value (a lambda
// in a variable/param) use (funcall f x) or (apply f args), as in Common Lisp.

include "std/core.lang"
include "std/tok.lang"
include "std/parser_reader.lang"
include "std/ast.lang"

// #parser{} generates a recursive descent parser from this grammar
#parser{
    sexp = number | symbol | operator | list
    list = '(' sexp* ')'
}

// PNODE kinds: 1=number, 2=symbol, 4=list, 5=operator

// ============================================================
// Parse tree helpers
// ============================================================

func list_inner(node *PNode) *PNode {
    return vec_get(node.children, 1);
}

func list_get(node *PNode, i i64) *PNode {
    return vec_get(list_inner(node).children, i);
}

func list_len(node *PNode) i64 {
    return vec_len(list_inner(node).children);
}

func is_sym(node *PNode, name *u8) bool {
    if node == nil { return false; }
    if node.kind != 2 { return false; }
    return streq(node.text, name);
}

// Runtime function for an n-ary arithmetic operator (foldable); nil otherwise.
func arith_fn(op *u8) *u8 {
    if streq(op, "+") { return "lisp_add"; }
    if streq(op, "-") { return "lisp_sub"; }
    if streq(op, "*") { return "lisp_mul"; }
    if streq(op, "/") { return "lisp_div"; }
    if streq(op, "%") { return "lisp_mod"; }
    return nil;
}

// Runtime function for a binary comparison operator; nil otherwise.
func cmp_fn(op *u8) *u8 {
    if streq(op, "<") { return "lisp_lt"; }
    if streq(op, ">") { return "lisp_gt"; }
    if streq(op, "<=") { return "lisp_le"; }
    if streq(op, ">=") { return "lisp_ge"; }
    if streq(op, "=") { return "lisp_num_eq"; }
    if streq(op, "==") { return "lisp_num_eq"; }
    if streq(op, "!=") { return "lisp_ne"; }
    return nil;
}

// Per-node-unique temp name, derived from the node's address (each `if` node is
// distinct). Avoids a module-global counter: the reader-build path drops globals
// declared in the reader's OWN file - only included-file globals survive.
func lisp_tmp(node *PNode) *u8 {
    var sb *StringBuilder = sb_new();
    sb_str(sb, "__lt");
    var addr i64 = node;
    sb_int(sb, addr);
    return sb_finish(sb);
}

// A boxed integer literal: (call lisp_int (number n))
func lisp_num_lit(n i64) *u8 {
    return ast_call_named1("lisp_int", ast_int(n));
}

// ============================================================
// Lowering: parse tree (PNode) -> lang AST calling the Lisp runtime
// ============================================================

// Left-fold a foldable runtime op over operands 1..hi:
// (+ a b c) with hi=3 -> lisp_add(lisp_add(a, b), c)
func lisp_fold(opfn *u8, node *PNode, hi i64) *u8 {
    if hi == 1 {
        return lisp_expr(list_get(node, 1));
    }
    return ast_call_named2(opfn, lisp_fold(opfn, node, hi - 1), lisp_expr(list_get(node, hi)));
}

// (let ((n1 v1) (n2 v2) ...) body) -> nested kernel lets. Sequential (let*-style):
// a later binding sees the earlier ones.
func lisp_let(bindings *PNode, i i64, count i64, body *PNode) *u8 {
    if i >= count {
        return lisp_expr(body);
    }
    var binding *PNode = list_get(bindings, i);
    var name *PNode = list_get(binding, 0);
    var valexpr *PNode = list_get(binding, 1);
    return ast_let(name.text, ast_type_i64(), lisp_expr(valexpr),
                   lisp_let(bindings, i + 1, count, body));
}

// The kernel closure type every Lisp lambda lowers to: closure(i64) i64
// (takes one arg - the Lisp argument list - and returns a Lisp value).
func lisp_closure_type() *u8 {
    var ptypes *u8 = ast_vec();
    ast_push(ptypes, ast_type_i64());
    return ast_type_closure(ptypes, ast_type_i64());
}

// Bind each Lisp param to an element of the kernel lambda's single __args list:
// param[0] = (car __args), param[1] = (car (cdr __args)), ... then run the body.
func lisp_lambda_binds(params *PNode, i i64, count i64, argexpr *u8, body *u8) *u8 {
    if i >= count { return body; }
    var pnode *PNode = list_get(params, i);
    return ast_let(pnode.text, ast_type_i64(),
                   ast_call_named1("lisp_car", argexpr),
                   lisp_lambda_binds(params, i + 1, count,
                                     ast_call_named1("lisp_cdr", argexpr), body));
}

// (lambda (params) body) -> a boxed closure VALUE. Every Lisp lambda becomes a
// kernel closure of uniform type closure(i64) i64: it takes the argument list,
// destructures it into the named params, and runs the body. Routing it through
// a closure-typed `var` forces the [tag][fn_ptr][captures] heap layout (the
// kernel auto-wraps a non-capturing lambda to tag=0 there), then lisp_closure
// boxes the pointer so the lambda is first-class. The holding var is uniquely
// named per node (block_expr vars leak to the enclosing scope, like `if` temps).
func lisp_lambda(params *PNode, bodynode *PNode) *u8 {
    var cvar *u8 = lisp_tmp(bodynode);
    var pvec *u8 = ast_vec();
    ast_push(pvec, ast_param("__args", ast_type_i64()));
    var inner *u8 = lisp_lambda_binds(params, 0, list_len(params),
                                      ast_ident("__args"), lisp_expr(bodynode));
    var lam *u8 = ast_lambda(pvec, ast_type_i64(), ast_block1(ast_return(inner)));
    var stmts *u8 = ast_vec();
    ast_push(stmts, ast_var(cvar, lisp_closure_type(), lam));
    return ast_block_expr(stmts, ast_call_named1("lisp_closure", ast_ident(cvar)));
}

// (list a b c) -> (cons a (cons b (cons c (nil))))
func lisp_list_from(node *PNode, i i64, count i64) *u8 {
    if i >= count {
        return ast_call_named0("lisp_nil");
    }
    return ast_call_named2("lisp_cons", lisp_expr(list_get(node, i)), lisp_list_from(node, i + 1, count));
}

// Quote: build a Lisp VALUE from the parse tree without evaluating. Numbers
// become boxed ints, symbols/operators become interned symbols, lists become
// cons chains. (quote (a (b 2))) -> (cons sym-a (cons (cons sym-b (cons 2 nil)) nil))
func lisp_quote(node *PNode) *u8 {
    if node == nil { return ast_call_named0("lisp_nil"); }
    if node.kind == 1 {                                       // number -> boxed int
        return ast_call_named1("lisp_int", ast_number(node.text));
    }
    if node.kind == 2 {                                       // symbol
        if streq(node.text, "nil") { return ast_call_named0("lisp_nil"); }
        return ast_call_named1("lisp_sym", ast_string(node.text));
    }
    if node.kind == 5 {                                       // operator symbol, e.g. '+
        return ast_call_named1("lisp_sym", ast_string(node.text));
    }
    if node.kind == 4 {                                       // list -> cons chain
        return lisp_quote_list(node, 0, list_len(node));
    }
    return ast_call_named0("lisp_nil");
}

func lisp_quote_list(node *PNode, i i64, count i64) *u8 {
    if i >= count { return ast_call_named0("lisp_nil"); }
    return ast_call_named2("lisp_cons", lisp_quote(list_get(node, i)),
                           lisp_quote_list(node, i + 1, count));
}

// Emit a call to runtime function `fnname` with the node's args 1..count-1.
func lisp_runtime_call(fnname *u8, node *PNode, count i64) *u8 {
    var args *u8 = ast_vec();
    var i i64 = 1;
    while i < count {
        ast_push(args, lisp_expr(list_get(node, i)));
        i = i + 1;
    }
    return ast_call_named(fnname, args);
}

// Emit a body in return (tail) position. A tail `if` becomes real control flow
// with a return in each branch, so recursive base cases actually stop.
func lisp_return(node *PNode) *u8 {
    if node != nil && node.kind == 4 {
        var first *PNode = list_get(node, 0);
        if is_sym(first, "if") {
            return ast_if(ast_call_named1("lisp_truthy", lisp_expr(list_get(node, 1))),
                          ast_block1(lisp_return(list_get(node, 2))),
                          ast_block1(lisp_return(list_get(node, 3))));
        }
    }
    return ast_return(lisp_expr(node));
}

// Lower one minilisp node to lang AST. A top-level (defun ...) becomes a
// (program (func ...)); everything else lowers to an expression (an i64 that is
// really a *LispObj).
func lisp_expr(node *PNode) *u8 {
    if node == nil { return ast_call_named0("lisp_nil"); }

    if node.kind == 1 {                              // number literal -> boxed int
        return ast_call_named1("lisp_int", ast_number(node.text));
    }
    if node.kind == 2 {                              // symbol
        if streq(node.text, "nil") { return ast_call_named0("lisp_nil"); }
        return ast_ident(node.text);
    }
    if node.kind == 5 { return ast_call_named0("lisp_nil"); }   // bare operator (n/a)
    if node.kind != 4 { return ast_call_named0("lisp_nil"); }   // only lists remain

    var count i64 = list_len(node);
    if count == 0 { return ast_call_named0("lisp_nil"); }
    var first *PNode = list_get(node, 0);

    // Operator-headed: arithmetic (foldable) or comparison (binary).
    if first.kind == 5 {
        var op *u8 = first.text;
        var af *u8 = arith_fn(op);
        if af != nil {
            if count == 2 {                          // unary, e.g. (- x) -> lisp_sub(0, x)
                return ast_call_named2(af, lisp_num_lit(0), lisp_expr(list_get(node, 1)));
            }
            return lisp_fold(af, node, count - 1);
        }
        var cf *u8 = cmp_fn(op);
        if cf != nil {
            return ast_call_named2(cf, lisp_expr(list_get(node, 1)), lisp_expr(list_get(node, 2)));
        }
        return ast_call_named0("lisp_nil");
    }

    // (defun name (params) body) -> (program (func name (params) i64 (block ...)))
    if is_sym(first, "defun") {
        var name *PNode = list_get(node, 1);
        var params *PNode = list_get(node, 2);
        var body *PNode = list_get(node, 3);
        var pvec *u8 = ast_vec();
        var pc i64 = list_len(params);
        var pi i64 = 0;
        while pi < pc {
            var pnode *PNode = vec_get(list_inner(params).children, pi);
            ast_push(pvec, ast_param(pnode.text, ast_type_i64()));
            pi = pi + 1;
        }
        return ast_program1(ast_func(name.text, pvec, ast_type_i64(),
                                     ast_block1(lisp_return(body))));
    }

    // (if cond then else) -> value-returning block_expr; only the taken branch
    // runs. Condition goes through lisp_truthy (only nil is false).
    if is_sym(first, "if") {
        var t *u8 = lisp_tmp(node);
        var stmts *u8 = ast_vec();
        ast_push(stmts, ast_var(t, ast_type_i64(), ast_int(0)));
        ast_push(stmts, ast_if(ast_call_named1("lisp_truthy", lisp_expr(list_get(node, 1))),
                               ast_block1(ast_assign(ast_ident(t), lisp_expr(list_get(node, 2)))),
                               ast_block1(ast_assign(ast_ident(t), lisp_expr(list_get(node, 3))))));
        return ast_block_expr(stmts, ast_ident(t));
    }

    // (quote expr) -> the literal value (no evaluation)
    if is_sym(first, "quote") {
        return lisp_quote(list_get(node, 1));
    }

    // (let ((n v)...) body)
    if is_sym(first, "let") {
        var bindings *PNode = list_get(node, 1);
        var body *PNode = list_get(node, 2);
        return lisp_let(bindings, 0, list_len(bindings), body);
    }

    // (lambda (params) body) -> a first-class closure value
    if is_sym(first, "lambda") {
        return lisp_lambda(list_get(node, 1), list_get(node, 2));
    }

    // (funcall fexpr a b ...) -> apply a value-position function (Lisp-2 style)
    if is_sym(first, "funcall") {
        return ast_call_named2("lisp_apply", lisp_expr(list_get(node, 1)),
                               lisp_list_from(node, 2, count));
    }

    // (apply fexpr arglist) -> apply to an already-built argument list
    if is_sym(first, "apply") {
        return ast_call_named2("lisp_apply", lisp_expr(list_get(node, 1)),
                               lisp_expr(list_get(node, 2)));
    }

    // Logical + list builtins -> runtime calls.
    if is_sym(first, "not")  { return lisp_runtime_call("lisp_not", node, count); }
    if is_sym(first, "and")  { return lisp_runtime_call("lisp_and", node, count); }
    if is_sym(first, "or")   { return lisp_runtime_call("lisp_or", node, count); }
    if is_sym(first, "cons") { return lisp_runtime_call("lisp_cons", node, count); }
    if is_sym(first, "car")  { return lisp_runtime_call("lisp_car", node, count); }
    if is_sym(first, "cdr")  { return lisp_runtime_call("lisp_cdr", node, count); }
    if is_sym(first, "eq")   { return lisp_runtime_call("lisp_eq", node, count); }
    if is_sym(first, "list") { return lisp_list_from(node, 1, count); }

    // Head is itself an expression, e.g. ((lambda (x) ...) 5) -> apply its value.
    if first.kind == 4 {
        return ast_call_named2("lisp_apply", lisp_expr(first), lisp_list_from(node, 1, count));
    }

    // Function call: (f a b) -> (call (ident f) a b)
    if first.kind == 2 {
        var args *u8 = ast_vec();
        var ai i64 = 1;
        while ai < count {
            ast_push(args, lisp_expr(list_get(node, ai)));
            ai = ai + 1;
        }
        return ast_call_named(first.text, args);
    }

    return ast_call_named0("lisp_nil");
}

reader minilisp(text *u8) *u8 {
    var t *Tokenizer = tok_new(text);
    var node *PNode = parse_sexp(t);
    return lisp_expr(node);
}

example/minipy/minipy.lang:
// ============================================================
// minipy - a language whose block delimiter is whitespace
// ============================================================
//
// The fifth polyglot language, and the first one you cannot parse by reading
// characters in order. C, flow and minilisp bracket their blocks, and forth has
// no blocks at all; minipy's block structure lives in the space to the LEFT of
// each line, which is exactly the part every other reader throws away:
//
//   #minipy{
//       def collatz(n):
//           steps = 0
//           while n != 1:
//               if n % 2 == 0:
//                   n = n / 2
//               else:
//                   n = 3 * n + 1
//               steps += 1
//           return steps
//   }
//
// The shared tokenizer (std/tok.lang) is deliberately whitespace-blind - it
// skips runs of spaces and newlines without recording them, and every other
// reader depends on that. Layout does NOT need it to change. A token carries its
// byte offset into the source (`tok_start`), so the two facts the offside rule
// actually needs - "is this the first token on its line" and "at what column" -
// are still recoverable, and recovering them is the reader's business, not the
// tokenizer's. py_lex below rebuilds them and emits the synthetic NEWLINE /
// INDENT / DEDENT tokens a layout language wants, which is precisely what
// CPython's tokenizer hands to its parser. Nothing shared was touched, so
// nothing else could break: layout is a plugin too.
//
// Two consequences of layout that the token stream then handles for free:
// a newline inside `( ... )` continues the line (bracket depth suppresses the
// rule), and a blank or comment-only line has no tokens at all, so it cannot
// affect indentation.
//
// Supported: def, if/elif/else, while, for-in-range, return, pass, break,
// continue, assignment and augmented assignment, `and`/`or`/`not`, the full
// Python precedence ladder down through the bitwise and shift operators,
// calls, `#` comments, and both quote styles. True/False/None are 1/0/0.
//
// Deliberate bounds (round 1): every value is an i64, so there are no lists,
// dicts, strings-as-values (a string literal may only be an argument to
// `print`), or floats; no classes, no lambdas, no nested defs or closures, no
// default/keyword arguments, no `import`, no exceptions, and only `def` at the
// top level. `for` iterates `range(...)` only. Chained comparisons (`a < b < c`)
// are rejected rather than silently mis-associated. Names are function-scoped as
// in Python (see py_def's hoist), NOT block-scoped as in lang.
//
// A call to a name minipy has never seen is emitted as an ordinary call, so
// minipy reaches C, minilisp, flow, forth and lang functions with no
// declaration of any kind - the i64 ABI is the whole interface.
//
// Converter helpers are py_-prefixed so minipy composes with the other readers
// in one binary (no symbol collisions).

include "std/core.lang"
include "std/ast.lang"
include "std/tok.lang"

// Synthetic token kinds, above anything std/tok.lang produces. These are the
// layout algorithm's entire output: the structure of the program.
var PY_NEWLINE i64 = 200;
var PY_INDENT i64 = 201;
var PY_DEDENT i64 = 202;

// ============================================================
// Source pre-pass
// ============================================================

// Blank out `#` comments and defuse `//`, without moving a single byte.
//
// Byte positions ARE the block structure here, so this pass must be
// length-preserving: a comment becomes spaces rather than disappearing, which
// also makes a comment-only line indistinguishable from a blank one - Python's
// rule, for free. `//` (floor division) has to be neutered because the shared
// tokenizer would eat the rest of the line as a lang comment; rewriting it to
// `/ ` keeps the length, and integer division is what `/` already means when
// every value is an i64.
func py_strip_comments(text *u8) *u8 {
    var sb *StringBuilder = sb_new();
    var p *u8 = text;
    var quote i64 = 0;
    while *p != 0 {
        var c i64 = *p;
        if quote != 0 {
            sb_char(sb, c);
            if c == 92 {
                if *(p + 1) != 0 {
                    p = p + 1;
                    sb_char(sb, *p);
                }
            } else if c == quote {
                quote = 0;
            }
        } else if c == 34 || c == 39 {
            quote = c;
            sb_char(sb, c);
        } else if c == 35 {
            while *p != 0 && *p != 10 {
                sb_char(sb, 32);
                p = p + 1;
            }
            if *p == 0 { return sb_finish(sb); }
            sb_char(sb, 10);
        } else if c == 47 && *(p + 1) == 47 {
            sb_char(sb, 47);
            sb_char(sb, 32);
            p = p + 1;
        } else {
            sb_char(sb, c);
        }
        p = p + 1;
    }
    return sb_finish(sb);
}

// ============================================================
// The token stream
// ============================================================
//
// Tokens are a flat vec of (kind, text, line, col) quadruples. A reader's own
// struct declarations are a road less travelled, and four parallel slots cost
// nothing next to that risk.

func py_emit(toks *u8, kind i64, text *u8, line i64, col i64) void {
    vec_push(toks, kind);
    vec_push(toks, text);
    vec_push(toks, line);
    vec_push(toks, col);
}

func py_k(toks *u8, i i64) i64 {
    if i * 4 >= vec_len(toks) { return TOK_EOF; }
    return vec_get(toks, i * 4);
}

func py_txt(toks *u8, i i64) *u8 {
    if i * 4 + 1 >= vec_len(toks) { return ""; }
    return vec_get(toks, i * 4 + 1);
}

func py_line(toks *u8, i i64) i64 {
    if i * 4 + 2 >= vec_len(toks) { return 0; }
    return vec_get(toks, i * 4 + 2);
}

// Offset of the first byte of the line containing `off`.
func py_line_start(text *u8, off i64) i64 {
    while off > 0 {
        if *(text + off - 1) == 10 { return off; }
        off = off - 1;
    }
    return 0;
}

func py_top(indents *u8) i64 {
    return vec_get(indents, vec_len(indents) - 1);
}

// The offside rule. Walks the ordinary token stream and inserts NEWLINE where a
// logical line ends and INDENT/DEDENT where the left margin moves.
//
// The base indent is taken from the FIRST token rather than assumed to be
// column 0, so a `#minipy{ ... }` block may sit at whatever indentation the
// host file uses - only the columns relative to that first line matter.
func py_lex(text *u8) *u8 {
    var t *Tokenizer = tok_new(text);
    var toks *u8 = vec_new(256);
    var indents *u8 = vec_new(16);
    vec_push(indents, 0);

    var depth i64 = 0;
    var prev_ls i64 = 0 - 1;
    var started i64 = 0;
    var line i64 = 1;
    var scanned i64 = 0;

    while tok_kind(t) != TOK_EOF {
        var start i64 = t.tok_start;
        while scanned < start {
            if *(text + scanned) == 10 { line = line + 1; }
            scanned = scanned + 1;
        }
        var ls i64 = py_line_start(text, start);
        var col i64 = start - ls;

        // Bracketed newlines are continuations, not statement ends.
        if depth == 0 && ls != prev_ls {
            if started == 0 {
                vec_set(indents, 0, col);
            } else {
                py_emit(toks, PY_NEWLINE, "", line, col);
                if col > py_top(indents) {
                    vec_push(indents, col);
                    py_emit(toks, PY_INDENT, "", line, col);
                } else {
                    while col < py_top(indents) {
                        vec_pop(indents);
                        py_emit(toks, PY_DEDENT, "", line, col);
                    }
                    if col != py_top(indents) {
                        eprint("minipy: line ");
                        eprint_i64(line);
                        eprint(": dedent does not match any enclosing block\n");
                    }
                }
            }
        }
        prev_ls = ls;
        started = 1;

        var k i64 = tok_kind(t);
        if k == TOK_LPAREN || k == TOK_LBRACKET || k == TOK_LBRACE {
            depth = depth + 1;
        }
        if k == TOK_RPAREN || k == TOK_RBRACKET || k == TOK_RBRACE {
            if depth > 0 { depth = depth - 1; }
        }
        // A string's text is its VALUE (unquoted, unescaped); the kind is what
        // says it was quoted, so nothing downstream needs to re-parse it.
        if k == TOK_STRING {
            py_emit(toks, k, tok_string_value(t), line, col);
        } else {
            py_emit(toks, k, tok_text(t), line, col);
        }
        tok_next(t);
    }

    if started == 1 { py_emit(toks, PY_NEWLINE, "", line, 0); }
    while vec_len(indents) > 1 {
        vec_pop(indents);
        py_emit(toks, PY_DEDENT, "", line, 0);
    }
    py_emit(toks, TOK_EOF, "", line, 0);
    return toks;
}

// ============================================================
// Token predicates
// ============================================================

func py_is_kw(toks *u8, i i64, kw *u8) i64 {
    if py_k(toks, i) != TOK_IDENT { return 0; }
    if streq(py_txt(toks, i), kw) { return 1; }
    return 0;
}

// Operators arrive as a kind plus their text, so `<`, `<=` and `<<` all share
// TOK_LT and are told apart here.
func py_is_op(toks *u8, i i64, kind i64, text *u8) i64 {
    if py_k(toks, i) != kind { return 0; }
    if streq(py_txt(toks, i), text) { return 1; }
    return 0;
}

var py_errors i64 = 0;

// Line numbers are relative to the `#minipy{` block, which is the only origin
// the reader is given.
func py_err(toks *u8, i i64, msg *u8) void {
    py_errors = py_errors + 1;
    eprint("minipy: line ");
    eprint_i64(py_line(toks, i));
    eprint(": ");
    eprint(msg);
    eprint("\n");
}

func py_expect(toks *u8, ip *i64, kind i64, what *u8) void {
    if py_k(toks, *ip) == kind {
        *ip = *ip + 1;
        return;
    }
    py_err(toks, *ip, what);
}

func py_expect_kw(toks *u8, ip *i64, kw *u8, what *u8) void {
    if py_is_kw(toks, *ip, kw) == 1 {
        *ip = *ip + 1;
        return;
    }
    py_err(toks, *ip, what);
}

// ============================================================
// Expressions - the Python precedence ladder
// ============================================================

func py_expr(toks *u8, ip *i64) *u8 {
    return py_or(toks, ip);
}

func py_or(toks *u8, ip *i64) *u8 {
    var e *u8 = py_and(toks, ip);
    while py_is_kw(toks, *ip, "or") == 1 {
        *ip = *ip + 1;
        e = ast_binop("||", e, py_and(toks, ip));
    }
    return e;
}

func py_and(toks *u8, ip *i64) *u8 {
    var e *u8 = py_not(toks, ip);
    while py_is_kw(toks, *ip, "and") == 1 {
        *ip = *ip + 1;
        e = ast_binop("&&", e, py_not(toks, ip));
    }
    return e;
}

func py_not(toks *u8, ip *i64) *u8 {
    if py_is_kw(toks, *ip, "not") == 1 {
        *ip = *ip + 1;
        return ast_not(py_not(toks, ip));
    }
    return py_cmp(toks, ip);
}

// The comparison operator at i, or nil. `<<` and `>>` are shifts, not
// comparisons, and are filtered out here by their text.
func py_cmp_op(toks *u8, i i64) *u8 {
    var k i64 = py_k(toks, i);
    var s *u8 = py_txt(toks, i);
    if k == TOK_LT {
        if streq(s, "<") { return "<"; }
        if streq(s, "<=") { return "<="; }
        return nil;
    }
    if k == TOK_GT {
        if streq(s, ">") { return ">"; }
        if streq(s, ">=") { return ">="; }
        return nil;
    }
    if k == TOK_EQ {
        if streq(s, "==") { return "=="; }
        return nil;
    }
    if k == TOK_BANG {
        if streq(s, "!=") { return "!="; }
        return nil;
    }
    return nil;
}

// Python's `a < b < c` means `a < b and b < c`, not `(a < b) < c`. Rather than
// quietly compile the wrong program, refuse it.
func py_cmp(toks *u8, ip *i64) *u8 {
    var e *u8 = py_bitor(toks, ip);
    var op *u8 = py_cmp_op(toks, *ip);
    if op == nil { return e; }
    *ip = *ip + 1;
    var rhs *u8 = py_bitor(toks, ip);
    if py_cmp_op(toks, *ip) != nil {
        py_err(toks, *ip, "chained comparison (a < b < c) is not supported");
    }
    return ast_binop(op, e, rhs);
}

func py_bitor(toks *u8, ip *i64) *u8 {
    var e *u8 = py_bitxor(toks, ip);
    while py_is_op(toks, *ip, TOK_PIPE, "|") == 1 {
        *ip = *ip + 1;
        e = ast_binop("|", e, py_bitxor(toks, ip));
    }
    return e;
}

func py_bitxor(toks *u8, ip *i64) *u8 {
    var e *u8 = py_bitand(toks, ip);
    while py_is_op(toks, *ip, TOK_CARET, "^") == 1 {
        *ip = *ip + 1;
        e = ast_binop("^", e, py_bitand(toks, ip));
    }
    return e;
}

func py_bitand(toks *u8, ip *i64) *u8 {
    var e *u8 = py_shift(toks, ip);
    while py_is_op(toks, *ip, TOK_AMP, "&") == 1 {
        *ip = *ip + 1;
        e = ast_binop("&", e, py_shift(toks, ip));
    }
    return e;
}

func py_shift(toks *u8, ip *i64) *u8 {
    var e *u8 = py_add(toks, ip);
    var go i64 = 1;
    while go == 1 {
        if py_is_op(toks, *ip, TOK_LT, "<<") == 1 {
            *ip = *ip + 1;
            e = ast_binop("<<", e, py_add(toks, ip));
        } else if py_is_op(toks, *ip, TOK_GT, ">>") == 1 {
            *ip = *ip + 1;
            e = ast_binop(">>", e, py_add(toks, ip));
        } else {
            go = 0;
        }
    }
    return e;
}

// The shared tokenizer folds a `-` straight into a following digit, so `n -1`
// arrives as `n` and the single number `-1` with no operator between them.
// Every infix reader has to undo that; forth's answer was to ban `-5` outright,
// which is not an option for a language people expect to write `i-1` in.
func py_neg_number(toks *u8, i i64) i64 {
    if py_k(toks, i) != TOK_NUMBER { return 0; }
    if *py_txt(toks, i) == 45 { return 1; }
    return 0;
}

func py_add(toks *u8, ip *i64) *u8 {
    var e *u8 = py_term(toks, ip);
    var go i64 = 1;
    while go == 1 {
        if py_is_op(toks, *ip, TOK_PLUS, "+") == 1 {
            *ip = *ip + 1;
            e = ast_binop("+", e, py_term(toks, ip));
        } else if py_is_op(toks, *ip, TOK_MINUS, "-") == 1 {
            *ip = *ip + 1;
            e = ast_binop("-", e, py_term(toks, ip));
        } else if py_neg_number(toks, *ip) == 1 {
            var t *u8 = py_txt(toks, *ip);
            *ip = *ip + 1;
            e = ast_binop("-", e, ast_number(t + 1));
        } else {
            go = 0;
        }
    }
    return e;
}

func py_term(toks *u8, ip *i64) *u8 {
    var e *u8 = py_unary(toks, ip);
    var go i64 = 1;
    while go == 1 {
        if py_is_op(toks, *ip, TOK_STAR, "*") == 1 {
            *ip = *ip + 1;
            e = ast_binop("*", e, py_unary(toks, ip));
        } else if py_is_op(toks, *ip, TOK_SLASH, "/") == 1 {
            *ip = *ip + 1;
            e = ast_binop("/", e, py_unary(toks, ip));
        } else if py_is_op(toks, *ip, TOK_PERCENT, "%") == 1 {
            *ip = *ip + 1;
            e = ast_binop("%", e, py_unary(toks, ip));
        } else {
            go = 0;
        }
    }
    return e;
}

func py_unary(toks *u8, ip *i64) *u8 {
    if py_is_op(toks, *ip, TOK_MINUS, "-") == 1 {
        *ip = *ip + 1;
        return ast_neg(py_unary(toks, ip));
    }
    if py_is_op(toks, *ip, TOK_PLUS, "+") == 1 {
        *ip = *ip + 1;
        return py_unary(toks, ip);
    }
    if py_is_op(toks, *ip, TOK_TILDE, "~") == 1 {
        *ip = *ip + 1;
        return ast_binop("^", py_unary(toks, ip), ast_neg(ast_int(1)));
    }
    return py_atom(toks, ip);
}

func py_args(toks *u8, ip *i64) *u8 {
    var args *u8 = ast_vec();
    py_expect(toks, ip, TOK_LPAREN, "expected '(' in call");
    while py_k(toks, *ip) != TOK_RPAREN && py_k(toks, *ip) != TOK_EOF {
        ast_push(args, py_expr(toks, ip));
        if py_k(toks, *ip) == TOK_COMMA { *ip = *ip + 1; }
    }
    py_expect(toks, ip, TOK_RPAREN, "unclosed call argument list");
    return args;
}

func py_atom(toks *u8, ip *i64) *u8 {
    var k i64 = py_k(toks, *ip);
    if k == TOK_NUMBER {
        var n *u8 = py_txt(toks, *ip);
        *ip = *ip + 1;
        return ast_number(n);
    }
    if k == TOK_STRING {
        py_err(toks, *ip, "a string may only be an argument to print in this subset");
        *ip = *ip + 1;
        return ast_int(0);
    }
    if k == TOK_LPAREN {
        *ip = *ip + 1;
        var e *u8 = py_expr(toks, ip);
        py_expect(toks, ip, TOK_RPAREN, "unclosed parenthesis");
        return e;
    }
    if k == TOK_IDENT {
        var name *u8 = py_txt(toks, *ip);
        if streq(name, "True")  { *ip = *ip + 1; return ast_int(1); }
        if streq(name, "False") { *ip = *ip + 1; return ast_int(0); }
        if streq(name, "None")  { *ip = *ip + 1; return ast_int(0); }
        *ip = *ip + 1;
        // Any name, defined here or in any other language in the binary.
        if py_k(toks, *ip) == TOK_LPAREN {
            return ast_call_named(name, py_args(toks, ip));
        }
        return ast_ident(name);
    }
    py_err(toks, *ip, "expected an expression");
    *ip = *ip + 1;
    return ast_int(0);
}

// ============================================================
// Statements
// ============================================================

func py_name_in(names *u8, name *u8) i64 {
    var n i64 = vec_len(names);
    var i i64 = 0;
    while i < n {
        var s *u8 = vec_get(names, i);
        if streq(s, name) { return 1; }
        i = i + 1;
    }
    return 0;
}

func py_note_local(locals *u8, name *u8) void {
    if py_name_in(locals, name) == 0 { vec_push(locals, name); }
}

// A per-token-unique name for a compiler-introduced temp.
func py_gensym(prefix *u8, idx i64) *u8 {
    var sb *StringBuilder = sb_new();
    sb_str(sb, prefix);
    sb_int(sb, idx);
    return sb_finish(sb);
}

// The augmented-assignment operator at i, or nil.
func py_aug_op(toks *u8, i i64) *u8 {
    var k i64 = py_k(toks, i);
    var s *u8 = py_txt(toks, i);
    if k == TOK_PLUS && streq(s, "+=") { return "+"; }
    if k == TOK_MINUS && streq(s, "-=") { return "-"; }
    if k == TOK_STAR && streq(s, "*=") { return "*"; }
    if k == TOK_SLASH && streq(s, "/=") { return "/"; }
    if k == TOK_PERCENT && streq(s, "%=") { return "%"; }
    return nil;
}

// `print(a, "b", c)` -> py_int(a); py_space(); py_str("b"); ... ; py_nl().
// Which call an argument becomes is decided from its syntax right here, which
// is how a variadic polymorphic builtin survives lowering into a language that
// has neither.
func py_print(toks *u8, ip *i64, stmts *u8) void {
    *ip = *ip + 1;
    py_expect(toks, ip, TOK_LPAREN, "expected '(' after print");
    var n i64 = 0;
    while py_k(toks, *ip) != TOK_RPAREN && py_k(toks, *ip) != TOK_EOF {
        if n > 0 { ast_push(stmts, ast_expr_stmt(ast_call_named0("py_space"))); }
        if py_k(toks, *ip) == TOK_STRING {
            var s *u8 = py_txt(toks, *ip);
            *ip = *ip + 1;
            ast_push(stmts, ast_expr_stmt(ast_call_named1("py_str", ast_string(s))));
        } else {
            ast_push(stmts, ast_expr_stmt(ast_call_named1("py_int", py_expr(toks, ip))));
        }
        n = n + 1;
        if py_k(toks, *ip) == TOK_COMMA { *ip = *ip + 1; }
    }
    py_expect(toks, ip, TOK_RPAREN, "unclosed print");
    ast_push(stmts, ast_expr_stmt(ast_call_named0("py_nl")));
}

// Statements that cannot contain a block.
func py_simple(toks *u8, ip *i64, stmts *u8, locals *u8) void {
    if py_k(toks, *ip) == TOK_IDENT {
        var w *u8 = py_txt(toks, *ip);
        if streq(w, "pass") { *ip = *ip + 1; return; }
        if streq(w, "break") {
            *ip = *ip + 1;
            ast_push(stmts, ast_break(nil));
            return;
        }
        if streq(w, "continue") {
            *ip = *ip + 1;
            ast_push(stmts, ast_continue(nil));
            return;
        }
        if streq(w, "return") {
            *ip = *ip + 1;
            if py_k(toks, *ip) == PY_NEWLINE || py_k(toks, *ip) == TOK_SEMI {
                ast_push(stmts, ast_return(ast_int(0)));
            } else {
                ast_push(stmts, ast_return(py_expr(toks, ip)));
            }
            return;
        }
        if streq(w, "print") {
            if py_k(toks, *ip + 1) == TOK_LPAREN {
                py_print(toks, ip, stmts);
                return;
            }
        }
        if py_is_op(toks, *ip + 1, TOK_EQ, "=") == 1 {
            py_note_local(locals, w);
            *ip = *ip + 2;
            ast_push(stmts, ast_assign(ast_ident(w), py_expr(toks, ip)));
            return;
        }
        var aug *u8 = py_aug_op(toks, *ip + 1);
        if aug != nil {
            py_note_local(locals, w);
            *ip = *ip + 2;
            var rhs *u8 = py_expr(toks, ip);
            ast_push(stmts, ast_assign(ast_ident(w), ast_binop(aug, ast_ident(w), rhs)));
            return;
        }
    }
    ast_push(stmts, ast_expr_stmt(py_expr(toks, ip)));
}

// `:` followed by either an indented block or a one-line suite. Statements are
// appended to the caller's vec so a desugaring can wrap them (see py_for).
func py_block_into(toks *u8, ip *i64, stmts *u8, locals *u8) void {
    py_expect(toks, ip, TOK_COLON, "expected ':' to open a block");
    if py_k(toks, *ip) != PY_NEWLINE {
        py_simple(toks, ip, stmts, locals);
        while py_k(toks, *ip) == TOK_SEMI {
            *ip = *ip + 1;
            py_simple(toks, ip, stmts, locals);
        }
        if py_k(toks, *ip) == PY_NEWLINE { *ip = *ip + 1; }
        return;
    }
    *ip = *ip + 1;
    if py_k(toks, *ip) != PY_INDENT {
        py_err(toks, *ip, "expected an indented block");
        return;
    }
    *ip = *ip + 1;
    while py_k(toks, *ip) != PY_DEDENT && py_k(toks, *ip) != TOK_EOF {
        py_stmt(toks, ip, stmts, locals);
    }
    if py_k(toks, *ip) == PY_DEDENT { *ip = *ip + 1; }
}

func py_block(toks *u8, ip *i64, locals *u8) *u8 {
    var stmts *u8 = ast_vec();
    py_block_into(toks, ip, stmts, locals);
    return ast_block(stmts);
}

// `elif` is just an `if` in the else branch, so the keyword is skipped by the
// same line that skips `if`.
func py_if(toks *u8, ip *i64, stmts *u8, locals *u8) void {
    *ip = *ip + 1;
    var cond *u8 = py_expr(toks, ip);
    var then_b *u8 = py_block(toks, ip, locals);
    var else_b *u8 = nil;
    if py_is_kw(toks, *ip, "elif") == 1 {
        var eb *u8 = ast_vec();
        py_if(toks, ip, eb, locals);
        else_b = ast_block(eb);
    } else if py_is_kw(toks, *ip, "else") == 1 {
        *ip = *ip + 1;
        else_b = py_block(toks, ip, locals);
    }
    ast_push(stmts, ast_if(cond, then_b, else_b));
}

func py_while(toks *u8, ip *i64, stmts *u8, locals *u8) void {
    *ip = *ip + 1;
    var cond *u8 = py_expr(toks, ip);
    ast_push(stmts, ast_while(cond, py_block(toks, ip, locals)));
}

// A literal integer, optionally negated - the only form `range`'s step may
// take, because the direction of the loop test has to be known at read time.
func py_step_literal(toks *u8, ip *i64) i64 {
    var neg i64 = 0;
    if py_is_op(toks, *ip, TOK_MINUS, "-") == 1 {
        neg = 1;
        *ip = *ip + 1;
    }
    if py_k(toks, *ip) != TOK_NUMBER {
        py_err(toks, *ip, "range's step must be an integer literal");
        return 1;
    }
    var v i64 = py_str_to_int(py_txt(toks, *ip));
    *ip = *ip + 1;
    if neg == 1 { return 0 - v; }
    return v;
}

func py_str_to_int(s *u8) i64 {
    var neg i64 = 0;
    if *s == 45 {
        neg = 1;
        s = s + 1;
    }
    var n i64 = 0;
    while *s != 0 {
        n = n * 10 + (*s - 48);
        s = s + 1;
    }
    if neg == 1 { return 0 - n; }
    return n;
}

// `for v in range(start, limit, step): body`
//
//     __lim = limit
//     v = start - step
//     while 1:
//         v = v + step
//         if v >= __lim: break
//         body
//
// The step happens at the TOP of the body, not the bottom, so that `continue`
// still advances the loop - lang's `continue` jumps to the loop condition, and a
// bottom increment would be skipped, turning a Python `continue` into a hang.
// Biasing the initial value by one step is what buys that placement. Both range
// bounds are evaluated exactly once, as in Python.
func py_for(toks *u8, ip *i64, stmts *u8, locals *u8) void {
    var idx i64 = *ip;
    *ip = *ip + 1;
    if py_k(toks, *ip) != TOK_IDENT {
        py_err(toks, *ip, "expected a loop variable after 'for'");
        return;
    }
    var vname *u8 = py_txt(toks, *ip);
    py_note_local(locals, vname);
    *ip = *ip + 1;
    py_expect_kw(toks, ip, "in", "expected 'in' after the loop variable");
    if py_is_kw(toks, *ip, "range") == 0 {
        py_err(toks, *ip, "for may only iterate range(...) in this subset");
        return;
    }
    *ip = *ip + 1;
    py_expect(toks, ip, TOK_LPAREN, "expected '(' after range");

    var first *u8 = py_expr(toks, ip);
    var start *u8 = ast_int(0);
    var limit *u8 = first;
    var step i64 = 1;
    if py_k(toks, *ip) == TOK_COMMA {
        *ip = *ip + 1;
        start = first;
        limit = py_expr(toks, ip);
        if py_k(toks, *ip) == TOK_COMMA {
            *ip = *ip + 1;
            step = py_step_literal(toks, ip);
        }
    }
    py_expect(toks, ip, TOK_RPAREN, "unclosed range");
    if step == 0 {
        py_err(toks, idx, "range's step may not be zero");
        step = 1;
    }

    var lim_name *u8 = py_gensym("__py_lim", idx);
    ast_push(stmts, ast_var(lim_name, ast_type_i64(), limit));
    ast_push(stmts, ast_assign(ast_ident(vname), ast_binop("-", start, ast_int(step))));

    var body *u8 = ast_vec();
    ast_push(body, ast_assign(ast_ident(vname), ast_binop("+", ast_ident(vname), ast_int(step))));
    var cmp *u8 = ">=";
    if step < 0 { cmp = "<="; }
    ast_push(body, ast_if(ast_binop(cmp, ast_ident(vname), ast_ident(lim_name)),
                          ast_block1(ast_break(nil)), nil));
    py_block_into(toks, ip, body, locals);
    ast_push(stmts, ast_while(ast_int(1), ast_block(body)));
}

// Keywords that would otherwise fall through to an expression statement and
// compile to something quietly unrelated to what they mean in Python.
func py_unsupported_kw(w *u8) i64 {
    if streq(w, "class") { return 1; }
    if streq(w, "import") { return 1; }
    if streq(w, "from") { return 1; }
    if streq(w, "lambda") { return 1; }
    if streq(w, "try") { return 1; }
    if streq(w, "with") { return 1; }
    if streq(w, "yield") { return 1; }
    if streq(w, "global") { return 1; }
    if streq(w, "nonlocal") { return 1; }
    if streq(w, "assert") { return 1; }
    if streq(w, "del") { return 1; }
    if streq(w, "raise") { return 1; }
    return 0;
}

func py_stmt(toks *u8, ip *i64, stmts *u8, locals *u8) void {
    var k i64 = py_k(toks, *ip);
    if k == PY_NEWLINE {
        *ip = *ip + 1;
        return;
    }
    if k == TOK_IDENT {
        var w *u8 = py_txt(toks, *ip);
        if streq(w, "if") { py_if(toks, ip, stmts, locals); return; }
        if streq(w, "while") { py_while(toks, ip, stmts, locals); return; }
        if streq(w, "for") { py_for(toks, ip, stmts, locals); return; }
        if streq(w, "def") {
            py_err(toks, *ip, "nested functions are not supported");
            py_skip_line(toks, ip);
            return;
        }
        if py_unsupported_kw(w) == 1 {
            py_err(toks, *ip, "this statement is not in the minipy subset");
            py_skip_line(toks, ip);
            return;
        }
    }
    py_simple(toks, ip, stmts, locals);
    while py_k(toks, *ip) == TOK_SEMI {
        *ip = *ip + 1;
        py_simple(toks, ip, stmts, locals);
    }
    if py_k(toks, *ip) == PY_NEWLINE {
        *ip = *ip + 1;
    } else {
        py_err(toks, *ip, "unexpected token after a statement");
        py_skip_line(toks, ip);
    }
}

func py_skip_line(toks *u8, ip *i64) void {
    while py_k(toks, *ip) != PY_NEWLINE && py_k(toks, *ip) != TOK_EOF {
        *ip = *ip + 1;
    }
    if py_k(toks, *ip) == PY_NEWLINE { *ip = *ip + 1; }
}

func py_starts(s *u8, p *u8) i64 {
    while *p != 0 {
        if *s == 0 { return 0; }
        if *s != *p { return 0; }
        s = s + 1;
        p = p + 1;
    }
    return 1;
}

// ============================================================
// Definitions
// ============================================================

// `def f(a, b): body` -> func f(a i64, b i64) i64 { ... }
//
// Python scopes a name to the whole function no matter which branch assigns it;
// lang scopes a `var` to its enclosing block. Every assigned name is therefore
// collected while the body is parsed and declared once at the top, so an
// assignment inside an `if` is still visible after it - which is exactly the
// mismatch that would otherwise make a faithful-looking program fail to compile.
func py_def(toks *u8, ip *i64) *u8 {
    *ip = *ip + 1;
    if py_k(toks, *ip) != TOK_IDENT {
        py_err(toks, *ip, "expected a function name after 'def'");
        return nil;
    }
    var name *u8 = py_txt(toks, *ip);
    *ip = *ip + 1;
    py_expect(toks, ip, TOK_LPAREN, "expected '(' after the function name");

    var params *u8 = ast_vec();
    var pnames *u8 = vec_new(8);
    while py_k(toks, *ip) == TOK_IDENT {
        var pn *u8 = py_txt(toks, *ip);
        ast_push(params, ast_param(pn, ast_type_i64()));
        vec_push(pnames, pn);
        *ip = *ip + 1;
        if py_k(toks, *ip) == TOK_COMMA { *ip = *ip + 1; }
    }
    py_expect(toks, ip, TOK_RPAREN, "unclosed parameter list");

    var locals *u8 = vec_new(16);
    var body *u8 = ast_vec();
    py_block_into(toks, ip, body, locals);

    var all *u8 = ast_vec();
    var nl i64 = vec_len(locals);
    var i i64 = 0;
    while i < nl {
        var ln *u8 = vec_get(locals, i);
        if py_name_in(pnames, ln) == 0 {
            ast_push(all, ast_var(ln, ast_type_i64(), ast_int(0)));
        }
        i = i + 1;
    }
    var nb i64 = ast_vec_len(body);
    i = 0;
    while i < nb {
        ast_push(all, ast_vec_get(body, i));
        i = i + 1;
    }
    // A Python function that runs off the end returns None; here that is 0.
    var tail_returns i64 = 0;
    if nb > 0 {
        if py_starts(ast_vec_get(body, nb - 1), "(return") == 1 { tail_returns = 1; }
    }
    if tail_returns == 0 { ast_push(all, ast_return(ast_int(0))); }

    return ast_func(name, params, ast_type_i64(), ast_block(all));
}

func py_program(toks *u8) *u8 {
    var decls *u8 = ast_vec();
    var ip i64 = 0;
    while py_k(toks, ip) != TOK_EOF {
        var k i64 = py_k(toks, ip);
        if k == PY_NEWLINE || k == PY_INDENT || k == PY_DEDENT {
            ip = ip + 1;
        } else if py_is_kw(toks, ip, "def") == 1 {
            var f *u8 = py_def(toks, &ip);
            if f != nil { ast_push(decls, f); }
        } else {
            py_err(toks, ip, "only 'def' is allowed at the top level");
            py_skip_line(toks, &ip);
        }
    }
    return ast_program(decls);
}

reader minipy(text *u8) *u8 {
    var src *u8 = py_strip_comments(text);
    var prog *u8 = py_program(py_lex(src));
    // A reader that reports a syntax error and then hands back a program anyway
    // is how a bad parse turns into a mystery further down the pipeline - most
    // often a function that simply isn't there. Refuse to emit one.
    if py_errors > 0 {
        eprint("minipy: ");
        eprint_i64(py_errors);
        eprint(" error(s); not emitting a program\n");
        exit(1);
    }
    return prog;
}

example/flow/flow.lang:
// ============================================================
// flow - a tiny generator/coroutine language (the effects DSL)
// ============================================================
//
// The third polyglot language. Where C is imperative and minilisp is functional,
// flow is about CONTROL: generators that suspend and resume. It lowers to lang's
// algebraic effects (perform/handle/resume) - something neither C nor our Lisp
// can express. Built with #parser{} (Level 3) + the std/ast.lang builder (L1).
//
//   #flow{
//     gen fib(n) {                 // a stateful generator
//       var a = 0; var b = 1; var i = 0;
//       while i < n { yield a; var t = a + b; a = b; b = t; i = i + 1; }
//     }
//     func sum_fib(n) {            // a driver: runs the generator, sums the values
//       var total = 0;
//       for x in fib(n) { total = total + x; }
//       return total;
//     }
//   }
//
// `yield e` performs Yield(e); `for x in g(...) {body}` lowers to a handle that
// binds each yielded value to x, runs body, and resumes the generator. Both
// `gen` and `func` become ordinary i64 functions, callable from lang and C.
//
// Conditions are unparenthesized (`if c {}`, `while c {}`) - flow is its own
// little language, not C. Everything is i64. Requires:
//   include "example/flow/flow_runtime.lang"   (declares `effect Yield`)
//
// Converter helpers are fl_-prefixed so flow composes with the C and minilisp
// readers in one binary (no symbol collisions).

include "std/core.lang"
include "std/tok.lang"
include "std/parser_reader.lang"
include "std/ast.lang"

#parser{
    flow_program  = flow_decl+
    flow_decl     = flow_gendecl | flow_funcdecl
    flow_gendecl  = 'gen' symbol '(' flow_params ')' flow_block
    flow_funcdecl = 'func' symbol '(' flow_params ')' flow_block
    flow_params   = flow_paramitem*
    flow_paramitem = symbol | ','
    flow_block    = '{' flow_stmt* '}'
    flow_stmt     = flow_var | flow_yield | flow_send | flow_return | flow_if | flow_while | flow_forin | flow_exprstmt
    flow_var      = 'var' symbol '=' flow_expr ';'
    flow_yield    = 'yield' flow_expr ';'
    flow_send     = 'send' flow_expr ';'
    flow_return   = 'return' flow_expr ';'
    flow_if       = 'if' flow_expr flow_block flow_elses
    flow_elses    = flow_elsepart*
    flow_elsepart = 'else' flow_block
    flow_while    = 'while' flow_expr flow_block
    flow_forin    = 'for' symbol 'in' flow_call flow_block
    flow_call     = symbol '(' flow_args ')'
    flow_exprstmt = flow_expr ';'
    flow_expr     = flow_unary flow_oprest*
    flow_oprest   = operator flow_unary
    flow_unary    = flow_neg | flow_postfix
    flow_neg      = operator flow_postfix
    flow_postfix  = flow_primary flow_callopt*
    flow_callopt  = '(' flow_args ')'
    flow_args     = flow_argitem*
    flow_argitem  = flow_expr | ','
    flow_primary  = flow_yieldexpr | number | symbol | flow_paren
    flow_yieldexpr = 'yield' flow_expr
    flow_paren    = '(' flow_expr ')'
}

// PNode kinds: 1=number, 2=symbol, 4=list/seq, 5=operator, 0=literal marker

// ============================================================
// Expressions (flat operand/op list resolved by precedence climbing)
// ============================================================

func fl_prec(op *u8) i64 {
    if streq(op, "||") { return 1; }
    if streq(op, "&&") { return 2; }
    if streq(op, "==") { return 3; }
    if streq(op, "!=") { return 3; }
    if streq(op, "<") { return 4; }
    if streq(op, ">") { return 4; }
    if streq(op, "<=") { return 4; }
    if streq(op, ">=") { return 4; }
    if streq(op, "+") { return 5; }
    if streq(op, "-") { return 5; }
    if streq(op, "*") { return 6; }
    if streq(op, "/") { return 6; }
    if streq(op, "%") { return 6; }
    return 0;
}

// flow_expr = flow_unary flow_oprest* -> parallel operand/op vecs.
func fl_flatten(e *PNode, operands *u8, ops *u8) void {
    vec_push(operands, vec_get(e.children, 0));
    var star *PNode = vec_get(e.children, 1);
    var m i64 = vec_len(star.children);
    var i i64 = 0;
    while i < m {
        var orn *PNode = vec_get(star.children, i);   // flow_oprest = [op, unary]
        vec_push(ops, vec_get(orn.children, 0));
        vec_push(operands, vec_get(orn.children, 1));
        i = i + 1;
    }
}

func fl_emit_expr(e *PNode) *u8 {
    var operands *u8 = vec_new(8);
    var ops *u8 = vec_new(8);
    fl_flatten(e, operands, ops);
    var pos i64 = 0;
    return fl_climb(operands, ops, &pos, 0);
}

func fl_climb(operands *u8, ops *u8, posptr *i64, minprec i64) *u8 {
    var left *u8 = fl_emit_operand(vec_get(operands, *posptr));
    var nops i64 = vec_len(ops);
    while *posptr < nops {
        var opnode *PNode = vec_get(ops, *posptr);
        var p i64 = fl_prec(opnode.text);
        if p < minprec { return left; }
        *posptr = *posptr + 1;
        var right *u8 = fl_climb(operands, ops, posptr, p + 1);   // left-associative
        left = ast_binop(opnode.text, left, right);
    }
    return left;
}

// flow_unary = flow_neg | flow_postfix. flow_neg leads with an operator atom.
func fl_emit_operand(node *PNode) *u8 {
    var f *PNode = vec_get(node.children, 0);
    if f.kind == 5 {
        return ast_unop(f.text, fl_emit_postfix(vec_get(node.children, 1)));
    }
    return fl_emit_postfix(node);
}

// flow_postfix = flow_primary flow_callopt*  ->  fold calls left-to-right.
func fl_emit_postfix(pf *PNode) *u8 {
    var primary *PNode = vec_get(pf.children, 0);
    var ops *PNode = vec_get(pf.children, 1);
    var base *u8 = fl_emit_primary(primary);
    var n i64 = vec_len(ops.children);
    var i i64 = 0;
    while i < n {
        var op *PNode = vec_get(ops.children, i);     // flow_callopt = ['(', args, ')']
        base = ast_call(base, fl_emit_args(vec_get(op.children, 1)));
        i = i + 1;
    }
    return base;
}

func fl_emit_primary(p *PNode) *u8 {
    if p.kind == 1 { return ast_number(p.text); }
    if p.kind == 2 { return ast_ident(p.text); }
    if p.kind == 4 {
        // kind-4 primary is either flow_yieldexpr ['yield', expr] or flow_paren
        // ['(', expr, ')']. The keyword 'yield' lexes to a symbol node (kind 2);
        // '(' is a punctuation marker (kind 0). So a leading symbol => yield.
        var first *PNode = vec_get(p.children, 0);
        if first.kind == 2 {
            // yield as an expression: its value is what the driver resumed with.
            return ast_perform1("Yield", fl_emit_expr(vec_get(p.children, 1)));
        }
        return fl_emit_expr(vec_get(p.children, 1));   // flow_paren
    }
    return ast_int(0);
}

// flow_args = flow_argitem* ; argitem = flow_expr | ','. Build an arg vec.
func fl_emit_args(args *PNode) *u8 {
    var av *u8 = ast_vec();
    var items *u8 = args.children;
    var n i64 = vec_len(items);
    var i i64 = 0;
    while i < n {
        var it *PNode = vec_get(items, i);
        if it.kind != 0 { ast_push(av, fl_emit_expr(it)); }   // skip ',' markers
        i = i + 1;
    }
    return av;
}

// ============================================================
// Statements
// ============================================================

// Per-node-unique name (handler bindings + block vars; derive from node address).
func fl_gensym(prefix *u8, node *PNode) *u8 {
    var sb *StringBuilder = sb_new();
    sb_str(sb, prefix);
    var addr i64 = node;
    sb_int(sb, addr);
    return sb_finish(sb);
}

// send_target = the enclosing for-in's send-register name (nil if none), so a
// `send` nested inside an if/while still targets the right driver's resume value.
func fl_emit_block(block *PNode, send_target *u8) *u8 {
    var stmts *u8 = ast_vec();
    var sl *PNode = vec_get(block.children, 1);    // ['{', stmt*, '}']
    var n i64 = vec_len(sl.children);
    var i i64 = 0;
    while i < n {
        ast_push(stmts, fl_emit_stmt(vec_get(sl.children, i), send_target));
        i = i + 1;
    }
    return ast_block(stmts);
}

func fl_emit_stmt(s *PNode, send_target *u8) *u8 {
    var first *PNode = vec_get(s.children, 0);
    if first.kind == 2 {
        if streq(first.text, "var") {        // ['var', name, '=', expr, ';']
            var name *PNode = vec_get(s.children, 1);
            return ast_var(name.text, ast_type_i64(), fl_emit_expr(vec_get(s.children, 3)));
        }
        if streq(first.text, "yield") {      // ['yield', expr, ';'] -> perform Yield(expr)
            return ast_expr_stmt(ast_perform1("Yield", fl_emit_expr(vec_get(s.children, 1))));
        }
        if streq(first.text, "send") {       // ['send', expr, ';'] -> set the resume value
            var sexpr *u8 = fl_emit_expr(vec_get(s.children, 1));
            if send_target == nil {
                return ast_expr_stmt(sexpr);   // defensive: `send` outside a for-in body
            }
            return ast_assign(ast_ident(send_target), sexpr);
        }
        if streq(first.text, "return") {     // ['return', expr, ';']
            return ast_return(fl_emit_expr(vec_get(s.children, 1)));
        }
        if streq(first.text, "if") {         // ['if', cond, block, elses]
            var cond *u8 = fl_emit_expr(vec_get(s.children, 1));
            var then_b *u8 = fl_emit_block(vec_get(s.children, 2), send_target);
            var elses *PNode = vec_get(s.children, 3);
            var else_b *u8 = nil;
            if vec_len(elses.children) > 0 {
                var ep *PNode = vec_get(elses.children, 0);   // ['else', block]
                else_b = fl_emit_block(vec_get(ep.children, 1), send_target);
            }
            return ast_if(cond, then_b, else_b);
        }
        if streq(first.text, "while") {      // ['while', cond, block]
            return ast_while(fl_emit_expr(vec_get(s.children, 1)),
                             fl_emit_block(vec_get(s.children, 2), send_target));
        }
        if streq(first.text, "for") {
            return fl_emit_forin(s);
        }
    }
    return fl_emit_exprstmt(first);          // flow_exprstmt: first is the flow_expr
}

// Bare expression statement: peel a leading '=' as an assignment, else expr_stmt.
func fl_emit_exprstmt(expr *PNode) *u8 {
    var operands *u8 = vec_new(8);
    var ops *u8 = vec_new(8);
    fl_flatten(expr, operands, ops);
    if vec_len(ops) > 0 {
        var op0 *PNode = vec_get(ops, 0);
        if streq(op0.text, "=") {
            var lv *PNode = vec_get(operands, 0);
            var rpos i64 = 1;
            return ast_assign(fl_emit_operand(lv), fl_climb(operands, ops, &rpos, 1));
        }
    }
    var epos i64 = 0;
    return ast_expr_stmt(fl_climb(operands, ops, &epos, 0));
}

// for X in GEN(args) { body }  ->  drive the generator with a handle:
//   handle { GEN(args); } with {
//     return(__rv) => 0,
//     Yield(X, __k) => { var __send = 0; body; resume __k(__send); }
//   }
// The handler binds the yielded value to X and the continuation to __k; resuming
// runs the generator on to its next yield (carrying its locals across the gap).
// __send starts at 0 each value and is overwritten by any `send E;` in the body,
// so it flows back as the result of the generator's `yield` expression - making
// the channel bidirectional (a one-way generator simply never sends, resuming 0).
//   flow_forin = ['for', X, 'in', flow_call, block]
func fl_emit_forin(s *PNode) *u8 {
    var xvar *PNode = vec_get(s.children, 1);
    var call *PNode = vec_get(s.children, 3);    // flow_call = [name, '(', args, ')']
    var block *PNode = vec_get(s.children, 4);

    var gname *PNode = vec_get(call.children, 0);
    var gcall *u8 = ast_call_named(gname.text, fl_emit_args(vec_get(call.children, 2)));

    var kname *u8 = fl_gensym("__k", s);
    var rvname *u8 = fl_gensym("__rv", s);
    var sname *u8 = fl_gensym("__send", s);

    // handler body = init send register, the for-body statements (with `send`
    // targeting this loop's register), then resume the generator with it.
    var hstmts *u8 = ast_vec();
    ast_push(hstmts, ast_var(sname, ast_type_i64(), ast_int(0)));
    var sl *PNode = vec_get(block.children, 1);
    var n i64 = vec_len(sl.children);
    var i i64 = 0;
    while i < n {
        ast_push(hstmts, fl_emit_stmt(vec_get(sl.children, i), sname));
        i = i + 1;
    }
    ast_push(hstmts, ast_expr_stmt(ast_resume(ast_ident(kname), ast_ident(sname))));

    var eh *u8 = ast_effect_handler("Yield", xvar.text, kname, ast_block(hstmts));
    var ehs *u8 = ast_vec();
    ast_push(ehs, eh);
    var body *u8 = ast_block1(ast_expr_stmt(gcall));
    return ast_expr_stmt(ast_handle(body, ast_return_handler(rvname, ast_int(0)), ehs));
}

// ============================================================
// Declarations
// ============================================================

// flow_params = paramitem* ; paramitem = symbol | ','. All params are i64.
func fl_emit_params(params *PNode) *u8 {
    var pv *u8 = ast_vec();
    var items *u8 = params.children;
    var n i64 = vec_len(items);
    var i i64 = 0;
    while i < n {
        var it *PNode = vec_get(items, i);
        if it.kind == 2 { ast_push(pv, ast_param(it.text, ast_type_i64())); }
        i = i + 1;
    }
    return pv;
}

// Does the statement list end in a `return`? (If not, the function needs an
// implicit one - generators fall off the end and an i64 fn must terminate.)
func fl_ends_in_return(sl *PNode) i64 {
    var n i64 = vec_len(sl.children);
    if n == 0 { return 0; }
    var last *PNode = vec_get(sl.children, n - 1);
    var h *PNode = vec_get(last.children, 0);
    if h.kind == 2 {
        if streq(h.text, "return") { return 1; }
    }
    return 0;
}

// gen/func decl = [KW, name, '(', params, ')', block]. Both become (func name
// (params) i64 block) - the only difference is that a `gen` body uses `yield`
// and a `func` body uses `for-in`, but the lowering is identical. A trailing
// `return 0` is appended when the body doesn't end in a return (a generator just
// yields and falls off the end; its return value is the handle's ignored result).
func fl_emit_func(d *PNode) *u8 {
    var name *PNode = vec_get(d.children, 1);
    var params *PNode = vec_get(d.children, 3);
    var block *PNode = vec_get(d.children, 5);
    var sl *PNode = vec_get(block.children, 1);
    var stmts *u8 = ast_vec();
    var n i64 = vec_len(sl.children);
    var i i64 = 0;
    while i < n {
        ast_push(stmts, fl_emit_stmt(vec_get(sl.children, i), nil));
        i = i + 1;
    }
    if fl_ends_in_return(sl) == 0 {
        ast_push(stmts, ast_return(ast_int(0)));
    }
    return ast_func(name.text, fl_emit_params(params), ast_type_i64(), ast_block(stmts));
}

func fl_emit_program(prog *PNode) *u8 {
    var decls *u8 = ast_vec();
    var dl *u8 = prog.children;
    var n i64 = vec_len(dl);
    var i i64 = 0;
    while i < n {
        ast_push(decls, fl_emit_func(vec_get(dl, i)));
        i = i + 1;
    }
    return ast_program(decls);
}

reader flow(text *u8) *u8 {
    var t *Tokenizer = tok_new(text);
    var prog *PNode = parse_flow_program(t);
    return fl_emit_program(prog);
}

example/minilisp/lisp_runtime.lang:
// ============================================================
// lisp_runtime - boxed-value runtime for the minilisp reader
// ============================================================
//
// Every Lisp value is an i64 that is really a *LispObj pointer. The kernel
// treats pointers as i64, so the code the #minilisp{} reader emits stays
// uniformly i64 and just calls these helpers. Include this ONCE in any program
// that uses #minilisp{} (include-dedup gives a single shared copy).
//
//   tag 0 = int    a = value
//   tag 1 = nil
//   tag 2 = cons   a = car, b = cdr
//   tag 3 = symbol a = char* name (interned: one object per distinct name)
//   tag 4 = closure a = kernel closure ptr ([tag][fn_ptr][captures])

include "std/core.lang"

struct LispObj {
    tag i64;
    a i64;
    b i64;
}

// Canonical nil, lazily allocated. A global in this INCLUDED file is fine - the
// reader-build path only drops globals declared in the reader's OWN source file.
var lisp_nil_obj i64 = 0;

func lisp_nil() i64 {
    if lisp_nil_obj == 0 {
        var o *LispObj = alloc(24);
        o.tag = 1; o.a = 0; o.b = 0;
        lisp_nil_obj = o;
    }
    return lisp_nil_obj;
}

func lisp_int(n i64) i64 {
    var o *LispObj = alloc(24);
    o.tag = 0; o.a = n; o.b = 0;
    return o;
}

func lisp_cons(car i64, cdr i64) i64 {
    var o *LispObj = alloc(24);
    o.tag = 2; o.a = car; o.b = cdr;
    return o;
}

// Interned symbols: a Lisp list of every symbol made so far (0 = not yet inited).
// Interning means same name -> same object, so symbols compare by identity (eq).
var lisp_symtab i64 = 0;

func lisp_sym(name *u8) i64 {
    if lisp_symtab == 0 { lisp_symtab = lisp_nil(); }
    var cur i64 = lisp_symtab;
    while lisp_tag(cur) == 2 {
        var s i64 = lisp_car(cur);
        var so *LispObj = s;
        var sname *u8 = so.a;
        if streq(sname, name) { return s; }
        cur = lisp_cdr(cur);
    }
    var o *LispObj = alloc(24);
    o.tag = 3; o.a = name; o.b = 0;
    var sym i64 = o;
    lisp_symtab = lisp_cons(sym, lisp_symtab);
    return sym;
}

func lisp_is_sym(x i64) i64 {
    var o *LispObj = x;
    if o.tag == 3 { return 1; }
    return 0;
}

func lisp_sym_name(x i64) *u8 {
    var o *LispObj = x;
    return o.a;
}

func lisp_tag(x i64) i64 {
    var o *LispObj = x;
    return o.tag;
}

func lisp_is_nil(x i64) i64 {
    var o *LispObj = x;
    if o.tag == 1 { return 1; }
    return 0;
}

// Box a kernel closure pointer as a first-class Lisp value (so lambdas can be
// stored in lists, returned, passed around). The reader wraps the lambda in a
// closure-typed binding first, so `c` is always a [tag][fn_ptr][captures] struct.
func lisp_closure(c i64) i64 {
    var o *LispObj = alloc(24);
    o.tag = 4; o.a = c; o.b = 0;
    return o;
}

func lisp_is_closure(x i64) i64 {
    var o *LispObj = x;
    if o.tag == 4 { return 1; }
    return 0;
}

// Apply a boxed closure to an already-built Lisp argument list. Routing the
// kernel closure pointer through a closure-typed local hands the call to the
// kernel's tag-aware closure-call path (works for tag=0 and tag=1).
func lisp_apply(f i64, args i64) i64 {
    var o *LispObj = f;
    var c closure(i64) i64 = o.a;
    return c(args);
}

// Lisp truthiness: only nil is false (Common-Lisp style; 0 is truthy).
func lisp_truthy(x i64) i64 {
    var o *LispObj = x;
    if o.tag == 1 { return 0; }
    return 1;
}

func lisp_car(x i64) i64 {
    var o *LispObj = x;
    if o.tag == 2 { return o.a; }
    return lisp_nil();
}

func lisp_cdr(x i64) i64 {
    var o *LispObj = x;
    if o.tag == 2 { return o.b; }
    return lisp_nil();
}

func lisp_int_val(x i64) i64 {
    var o *LispObj = x;
    return o.a;
}

// Interop: extract a raw integer to call lang/C functions across syntaxes.
func lisp_to_int(x i64) i64 {
    var o *LispObj = x;
    return o.a;
}

func lisp_add(x i64, y i64) i64 { return lisp_int(lisp_int_val(x) + lisp_int_val(y)); }
func lisp_sub(x i64, y i64) i64 { return lisp_int(lisp_int_val(x) - lisp_int_val(y)); }
func lisp_mul(x i64, y i64) i64 { return lisp_int(lisp_int_val(x) * lisp_int_val(y)); }
func lisp_div(x i64, y i64) i64 { return lisp_int(lisp_int_val(x) / lisp_int_val(y)); }
func lisp_mod(x i64, y i64) i64 { return lisp_int(lisp_int_val(x) % lisp_int_val(y)); }

// Comparisons return canonical true (int 1) or nil.
func lisp_bool(b i64) i64 {
    if b != 0 { return lisp_int(1); }
    return lisp_nil();
}
func lisp_lt(x i64, y i64) i64 { return lisp_bool(lisp_int_val(x) < lisp_int_val(y)); }
func lisp_gt(x i64, y i64) i64 { return lisp_bool(lisp_int_val(x) > lisp_int_val(y)); }
func lisp_le(x i64, y i64) i64 { return lisp_bool(lisp_int_val(x) <= lisp_int_val(y)); }
func lisp_ge(x i64, y i64) i64 { return lisp_bool(lisp_int_val(x) >= lisp_int_val(y)); }
func lisp_num_eq(x i64, y i64) i64 { return lisp_bool(lisp_int_val(x) == lisp_int_val(y)); }
func lisp_ne(x i64, y i64) i64 { return lisp_bool(lisp_int_val(x) != lisp_int_val(y)); }

// Logical ops. Eager (args already evaluated) - fine for pure code; short-circuit
// would need a block_expr desugar (a refinement for when side effects land).
func lisp_not(x i64) i64 { return lisp_bool(lisp_truthy(x) == 0); }
func lisp_and(x i64, y i64) i64 { if lisp_truthy(x) != 0 { return y; } return x; }
func lisp_or(x i64, y i64) i64 { if lisp_truthy(x) != 0 { return x; } return y; }

// eq: ints compare by value, everything else by identity.
func lisp_eq(x i64, y i64) i64 {
    var ox *LispObj = x;
    var oy *LispObj = y;
    if ox.tag != oy.tag { return lisp_nil(); }
    if ox.tag == 0 { return lisp_bool(ox.a == oy.a); }
    return lisp_bool(x == y);
}

// Print a value: int, nil, or (a b c ...).
func lisp_print(x i64) void {
    var o *LispObj = x;
    if o.tag == 0 { print_int(o.a); return; }
    if o.tag == 1 { print("nil"); return; }
    if o.tag == 3 { var nm *u8 = o.a; print(nm); return; }
    if o.tag == 4 { print("<closure>"); return; }
    if o.tag == 2 {
        print("(");
        var cur i64 = x;
        var first i64 = 1;
        while lisp_tag(cur) == 2 {
            if first == 0 { print(" "); }
            first = 0;
            lisp_print(lisp_car(cur));
            cur = lisp_cdr(cur);
        }
        if lisp_is_nil(cur) == 0 {     // improper tail
            print(" . ");
            lisp_print(cur);
        }
        print(")");
        return;
    }
    print("?");
}
